                      {aiAnalysis}
                    </div>
                  </div>
                  {/* Extract and highlight games */}
                  {(() => {
                    const extractGames = (text: string) => {
                      const games: { numbers: number[]; confidence: number; strategy: string }[] = [];
                      const lines = text.split("\n");

                      // Method 1: GAME_START/GAME_END blocks (fallback format)
                      let inGameBlock = false;
                      let blockLines: string[] = [];
                      for (const line of lines) {
                        if (line.trim() === "GAME_START") {
                          inGameBlock = true;
                          blockLines = [];
                          continue;
                        }
                        if (line.trim() === "GAME_END") {
                          inGameBlock = false;
                          // Parse block
                          let strategy = "", confidence = 0, numbers: number[] = [];
                          for (const bl of blockLines) {
                            const jogoMatch = bl.match(/Jogo\s+\d+\s*[-—–:]\s*(.+?)(?:\(|$)/i);
                            if (jogoMatch) strategy = jogoMatch[1].replace(/\*+/g, "").trim();
                            const confM = bl.match(/Confiança:\s*(\d+)/i) || bl.match(/(\d+)\s*\/\s*100/);
                            if (confM) confidence = parseInt(confM[1]);
                            const dezM = bl.match(/Dezenas?:\s*([\d,\s]+)/i);
                            if (dezM) {
                              numbers = dezM[1].split(/[,\s]+/).map(n => parseInt(n.trim())).filter(n => !isNaN(n) && n > 0 && n <= 100);
                            }
                          }
                          if (numbers.length >= 5) games.push({ numbers, confidence, strategy });
                          continue;
                        }
                        if (inGameBlock) blockLines.push(line);
                      }

                      if (games.length >= 3) return games;

                      // Method 2: AI format - detect "Jogo X" headers
                      for (let i = 0; i < lines.length; i++) {
                        const line = lines[i];
                        const isGameHeader = /(?:\*\*\s*)?Jogo\s+\d+/i.test(line) || /^\d+[.)]\s*(?:\*\*)?(?:Jogo|Aposta)/i.test(line);
                        if (!isGameHeader) continue;

                        const stratMatch = line.match(/(?:Jogo\s+\d+\s*[—–\-:]\s*\*?\*?)([^(*\n]+)/i);
                        const strategy = stratMatch ? stratMatch[1].replace(/\*+/g, "").trim() : "";
                        const confMatch = line.match(/Confiança:\s*(\d+)/i) || line.match(/(\d+)\s*\/\s*100/);
                        const confidence = confMatch ? parseInt(confMatch[1]) : 0;

                        let numbers: number[] = [];
                        for (let j = i; j < Math.min(i + 6, lines.length); j++) {
                          const dezMatch = lines[j].match(/Dezenas?:\s*([\d,\s]+)/i);
                          if (dezMatch) {
                            numbers = dezMatch[1].split(/[,\s]+/).map(n => parseInt(n.trim())).filter(n => !isNaN(n) && n > 0 && n <= 100);
                            break;
                          }
                          if (j > i) {
                            const numsInLine = lines[j].match(/\b(\d{1,3})\b/g);
                            if (numsInLine && numsInLine.length >= 5) {
                              numbers = numsInLine.map(n => parseInt(n)).filter(n => n > 0 && n <= 100);
                              if (numbers.length >= 5) break;
                              numbers = [];
                            }
                          }
                        }

                        if (numbers.length >= 5) {
                          games.push({ numbers, confidence, strategy });
                        }
                      }
                      return games;
                    };

                    const games = extractGames(aiAnalysis);
                    if (games.length < 1) return null;

                    return (
                      <Card className="border-primary/30 bg-gradient-to-br from-primary/5 to-accent/5 mt-6">
                        <CardHeader className="pb-3">
                          <CardTitle className="text-base flex items-center gap-2">
                            <Target className="h-5 w-5 text-primary" />
                            🎯 {games.length} Jogos Otimizados — Resumo Visual
                          </CardTitle>
                        </CardHeader>
                        <CardContent>
                          <div className="grid md:grid-cols-2 gap-3">
                            {games.slice(0, 10).map((game, idx) => {
                              const borderColor = idx < 3 ? "border-green-500/30" : idx < 6 ? "border-primary/30" : idx < 8 ? "border-orange-500/30" : "border-purple-500/30";
                              const badgeVariant: "default" | "secondary" | "outline" = idx < 3 ? "default" : idx < 6 ? "secondary" : "outline";
                              return (
                                <Card key={idx} className={`${borderColor} border`}>
                                  <CardContent className="pt-3 pb-3 px-4">
                                    <div className="flex items-center justify-between mb-2">
                                      <span className="font-semibold text-sm">Jogo {idx + 1}</span>
                                      <div className="flex items-center gap-2">
                                        {game.strategy && <Badge variant={badgeVariant} className="text-[10px]">{game.strategy}</Badge>}
                                        {game.confidence > 0 && (
                                          <Badge variant="outline" className="text-[10px] font-mono">{game.confidence}/100</Badge>
                                        )}
                                      </div>
                                    </div>
                                    <div className="flex flex-wrap gap-1.5">
                                      {game.numbers.map((n, ni) => (
                                        <span key={ni} className="inline-flex items-center justify-center w-8 h-8 rounded-full bg-primary/15 text-primary font-bold text-xs border border-primary/30">
                                          {String(n).padStart(2, "0")}
                                        </span>
                                      ))}
                                    </div>
                                  </CardContent>
                                </Card>
                              );
                            })}
                          </div>
                        </CardContent>
                      </Card>
                    );
                  })()}
                </div>
              ) : (
                <div className="text-center py-8">
                  <Brain className="mx-auto h-12 w-12 text-muted-foreground/30 mb-4" />
                  <p className="text-muted-foreground mb-4">
                    Clique abaixo para a IA analisar todos os dados e gerar 10 jogos otimizados para o prêmio principal.
                  </p>
                  <Button onClick={runAIAnalysis} disabled={aiLoading} className="gap-2">
                    {aiLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
                    Executar Análise IA + 10 Jogos
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState } from "react";
import { LotteryConfig, DrawResult } from "@/data/lotteries";
import { NumberStats } from "@/engine/statistics";
import { motion, AnimatePresence } from "framer-motion";
import { Brain, Loader2, Copy, Check, Star, Sparkles, RefreshCw, AlertTriangle } from "lucide-react";
import { GameAnalysisBlock } from "@/components/GameAnalysisBlock";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { generateNativeBets } from "@/engine/native-analysis";

interface Props {
  config: LotteryConfig;
  stats: NumberStats[];
  draws: DrawResult[];
  onSaveBet?: (numbers: number[], strategy?: string, score?: number, grade?: string) => void;
}

export function AIPredictionPanel({ config, stats, draws, onSaveBet }: Props) {
  const [bets, setBets] = useState<number[][]>([]);
  const [analysis, setAnalysis] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState<number | null>(null);
  const [saved, setSaved] = useState<Set<number>>(new Set());
  const [count, setCount] = useState(3);
  const [quality, setQuality] = useState<{ avgScore: number; scores: number[]; details?: string[][]; grade: string } | null>(null);

  const generate = async () => {
    setLoading(true);
    setBets([]);
    setAnalysis("");
    setQuality(null);
    try {
      // Native generation — no AI credits needed
      await new Promise(r => setTimeout(r, 300)); // Brief delay for UX
      const result = generateNativeBets(stats, config, draws, count);

      setBets(result.bets);
      setAnalysis(result.analysis);
      setQuality(result.quality);
      setSaved(new Set());
      toast.success(`${result.bets.length} apostas geradas! Qualidade: ${result.quality.grade}`);
    } catch (e: any) {
      console.error("Native prediction error:", e);
      toast.error(e?.message || "Erro ao gerar predições");
    } finally {
      setLoading(false);
    }
  };

  const copyBet = (bet: number[], index: number) => {
    navigator.clipboard.writeText(bet.join(" - "));
    setCopied(index);
    toast.success("Aposta copiada!");
    setTimeout(() => setCopied(null), 2000);
  };

  const handleSave = (bet: number[], index: number) => {
    onSaveBet?.(bet, "IA Nativa v2.0");
    setSaved(prev => new Set([...prev, index]));
  };

  const copyAll = () => {
    const text = bets.map((b, i) => `#${i + 1}: ${b.join(" - ")}`).join("\n");
    navigator.clipboard.writeText(text);
    toast.success("Todas as apostas copiadas!");
  };

  return (
    <div className="rounded-xl glass-card p-5 border border-primary/20 relative overflow-hidden">
      {/* Glow effect */}
      <div className="absolute inset-0 bg-gradient-to-br from-primary/5 via-transparent to-accent/5 pointer-events-none" />

      <div className="relative z-10">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-primary/10 border border-primary/20 flex items-center justify-center">
              <Brain className="w-4 h-4 text-primary" />
            </div>
            <div>
              <h3 className="text-sm font-semibold text-foreground flex items-center gap-1.5">
                IA Nativa v2.0
                <span className="text-[9px] px-1.5 py-0.5 rounded-full bg-primary/10 text-primary font-medium">
                  Motor Estatístico
                </span>
              </h3>
              <p className="text-[10px] text-muted-foreground mt-0.5">
                Frequência + Markov + Ciclos + Co-ocorrência + Entropia — sem custo de créditos
              </p>
            </div>
          </div>
          {quality && (
            <div className="flex items-center gap-2">
              <span className={`text-xs font-bold px-2 py-1 rounded-md ${
                quality.grade === "S" ? "bg-yellow-500/20 text-yellow-400" :
                quality.grade === "A" ? "bg-green-500/20 text-green-400" :
                quality.grade === "B" ? "bg-blue-500/20 text-blue-400" :
                "bg-muted text-muted-foreground"
              }`}>
                {quality.grade} ({quality.avgScore}pts)
              </span>
            </div>
          )}
          {bets.length > 0 && (
            <Button size="sm" variant="outline" onClick={copyAll} className="text-xs border-border/50">
              <Copy className="w-3 h-3 mr-1" /> Copiar todas
            </Button>
          )}
        </div>

        {/* Count selector + Generate */}
        <div className="flex items-center gap-2 mb-4">
          <div className="flex items-center gap-1">
            {[1, 3, 5, 10].map(n => (
              <button
                key={n}
                onClick={() => setCount(n)}
                className={`text-xs px-3 py-1.5 rounded-md border transition-all ${
                  count === n
                    ? "border-primary text-primary bg-primary/10"
                    : "border-border text-muted-foreground hover:text-foreground"
                }`}
              >
                {n}
              </button>
            ))}
          </div>
          <Button
            onClick={generate}
            disabled={loading}
            size="sm"
            className="text-xs gap-1.5 bg-primary hover:bg-primary/90"
          >
            {loading ? (
              <>
                <Loader2 className="w-3 h-3 animate-spin" />
                Analisando...
              </>
            ) : (
              <>
                <Sparkles className="w-3 h-3" />
                Gerar com IA
              </>
            )}
          </Button>
        </div>

        {/* Analysis text */}
        {analysis && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="mb-4 p-3 rounded-lg bg-muted/30 border border-border/30"
          >
            <p className="text-xs text-muted-foreground leading-relaxed">
              <Brain className="w-3 h-3 inline mr-1 text-primary" />
              {analysis}
            </p>
          </motion.div>
        )}

        {/* Loading state */}
        {loading && (
          <div className="flex flex-col items-center justify-center py-12 gap-3">
            <div className="relative">
              <div className="w-12 h-12 rounded-full border-2 border-primary/20 border-t-primary animate-spin" />
              <Brain className="w-5 h-5 text-primary absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
            </div>
            <p className="text-xs text-muted-foreground animate-pulse">
              A IA está analisando padrões de 100 sorteios...
            </p>
          </div>
        )}

        {/* Bets list */}
        <AnimatePresence mode="wait">
          <div className="space-y-2 max-h-96 overflow-y-auto">
            {bets.map((bet, i) => (
              <motion.div
                key={`ai-${i}-${bet.join(",")}`}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: i * 0.08 }}
                className="flex flex-col gap-1.5 p-3 rounded-lg bg-secondary/30 border border-primary/10 hover:border-primary/30 transition-colors group"
              >
                <div className="flex items-center gap-2">
                  <span className="text-xs text-primary font-mono w-6 font-semibold">#{i + 1}</span>
                  {quality?.scores?.[i] !== undefined && (
                    <span className={`text-[10px] font-mono px-1.5 py-0.5 rounded ${
                      quality.scores[i] >= 90 ? "bg-yellow-500/20 text-yellow-400" :
                      quality.scores[i] >= 80 ? "bg-green-500/20 text-green-400" :
                      quality.scores[i] >= 70 ? "bg-blue-500/20 text-blue-400" :
                      "bg-muted text-muted-foreground"
                    }`}>{quality.scores[i]}pts</span>
                  )}
                  <div className="flex flex-wrap gap-1.5 flex-1">
                    {bet.map(n => {
                      const stat = stats.find(s => s.number === n);
                      const ballClass =
                        stat?.status === "hot"
                          ? "lottery-ball-hot"
                          : stat?.status === "cold"
                          ? "lottery-ball-cold"
                          : "";
                      return (
                        <span key={n} className={`lottery-ball text-xs w-8 h-8 ${ballClass}`}>
                          {String(n).padStart(2, "0")}
                        </span>
                      );
                    })}
                  </div>
                  <div className="flex items-center gap-1">
                    {onSaveBet && (
                      <button
                        onClick={() => handleSave(bet, i)}
                        className={`transition-colors p-1 rounded-md ${
                          saved.has(i)
                            ? "text-yellow-400"
                            : "text-muted-foreground hover:text-yellow-400 hover:bg-yellow-400/5 opacity-0 group-hover:opacity-100"
                        }`}
                        disabled={saved.has(i)}
                      >
                        <Star className={`w-4 h-4 ${saved.has(i) ? "fill-yellow-400" : ""}`} />
                      </button>
                    )}
                    <button
                      onClick={() => copyBet(bet, i)}
                      className="text-muted-foreground hover:text-primary transition-colors p-1 rounded-md hover:bg-primary/5"
                    >
                      {copied === i ? (
                        <Check className="w-4 h-4 text-primary" />
                      ) : (
                        <Copy className="w-4 h-4" />
                      )}
                    </button>
                  </div>
                </div>
                {quality?.details?.[i] && quality.details[i].length > 0 && (
                  <div className="flex flex-wrap gap-1 ml-8">
                    {quality.details[i].map((detail: string, j: number) => (
                      <span key={j} className={`text-[9px] px-1.5 py-0.5 rounded-full ${
                        detail.startsWith("⚠") ? "bg-destructive/10 text-destructive" : "bg-primary/10 text-primary"
                      }`}>{detail}</span>
                    ))}
                  </div>
                )}
                <div className="ml-8">
                  <GameAnalysisBlock numbers={bet} stats={stats} config={config} draws={draws} />
                </div>
              </motion.div>
            ))}
          </div>
        </AnimatePresence>

        {!loading && bets.length === 0 && (
          <div className="text-center py-8 text-muted-foreground text-sm border border-dashed border-primary/20 rounded-lg">
            <Brain className="w-6 h-6 mx-auto mb-2 text-primary/40" />
            Clique em "Gerar com IA" para obter palpites inteligentes
          </div>
        )}
      </div>
    </div>
  );
}

