          </h3>
          <p className="text-xs text-muted-foreground">
            Insira múltiplos jogos e compare o desempenho contra sorteios reais
          </p>
        </div>
      </div>

      {/* Input area */}
      <div className="flex flex-col sm:flex-row gap-2 mb-3">
        <Input
          value={inputValue}
