          <div className="space-y-2">
            <label className="text-xs font-medium text-muted-foreground flex items-center gap-1">
              <Target className="w-3 h-3" /> Soma: {conditions.sumRange[0]}–{conditions.sumRange[1]}
            </label>
            <Slider
