          </div>
        </div>

        {/* Run button */}
        <Button onClick={runSimulation} disabled={running} className="w-full gap-2" size="lg">
          {running ? (
            <><Zap className="w-4 h-4 animate-pulse" />Simulando {totalGames.toLocaleString()} jogos...</>
