function GameCard({ game, rank, config, drawCount }: {
  game: SimulatedGame; rank: number; config: LotteryConfig; drawCount: number;
}) {
  const prizeRate = (game.prizeCount / drawCount * 100).toFixed(1);
  const medalColors: Record<number, string> = {
    1: "text-yellow-400",
    2: "text-gray-300",
    3: "text-amber-600",
  };

  return (
    <div className="p-3 rounded-lg bg-muted/20 border border-border hover:border-primary/30 transition-colors">
      <div className="flex items-start gap-3">
        <span className={`text-lg font-bold font-mono w-8 text-right shrink-0 ${medalColors[rank] || "text-muted-foreground"}`}>
          #{rank}
        </span>
        <div className="flex-1 min-w-0">
          <div className="flex flex-wrap gap-1 mb-2">
            {game.numbers.map((n, i) => (
              <span key={i} className="inline-flex items-center justify-center w-7 h-7 rounded-md bg-primary/10 text-primary text-xs font-mono font-bold border border-primary/20">
                {n.toString().padStart(2, "0")}
              </span>
            ))}
          </div>
          <div className="flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-muted-foreground">
            <span>Score: <strong className="text-primary">{game.score}</strong></span>
            <span>Média: <strong className="text-foreground">{game.avgHits}</strong></span>
            <span>Melhor: <strong className="text-foreground">{game.bestHit}/{config.pick}</strong></span>
            <span>Prêmios: <strong className="text-foreground">{prizeRate}%</strong></span>
            <span>P/I: <strong className="text-foreground">{game.evenCount}/{game.oddCount}</strong></span>
            <span>Soma: <strong className="text-foreground">{game.sum}</strong></span>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { NumberStats } from "@/engine/statistics";
import { DrawResult, LotteryConfig } from "@/data/lotteries";
import { STRATEGIES, Strategy } from "@/engine/strategies";
import type { MassiveSimResult } from "@/engine/massive-simulator";
import MonteCarloWorker from "@/workers/monte-carlo.worker?worker";
import { motion, AnimatePresence } from "framer-motion";
import {
  Rocket, Play, Trophy, TrendingUp, BarChart3,
  Calendar, Zap, CheckCircle2
} from "lucide-react";
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell,
  LineChart, Line, CartesianGrid, Legend,
} from "recharts";

interface Props {
  stats: NumberStats[];
  config: LotteryConfig;
  draws: DrawResult[];
}

const ITERATION_OPTIONS = [
  { label: "10K", value: 10_000 },
  { label: "50K", value: 50_000 },
  { label: "100K", value: 100_000 },
  { label: "500K", value: 500_000 },
  { label: "1M", value: 1_000_000 },
];

const STRATEGY_COLORS = [
  "hsl(142, 70%, 45%)",
  "hsl(200, 90%, 50%)",
  "hsl(280, 70%, 55%)",
  "hsl(45, 95%, 55%)",
  "hsl(0, 80%, 55%)",
  "hsl(170, 70%, 45%)",
];

export function MassiveSimulatorPanel({ stats, config, draws }: Props) {
  const [iterations, setIterations] = useState(50_000);
  const [selectedStrategies, setSelectedStrategies] = useState<Strategy[]>(["smart", "hot", "cycle", "hybrid"]);
  const [running, setRunning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<MassiveSimResult | null>(null);
  const workerRef = useRef<Worker | null>(null);

  // Reset state when lottery changes
  const prevLotteryId = useRef(config.id);
  useEffect(() => {
    if (prevLotteryId.current !== config.id) {
      prevLotteryId.current = config.id;
      setResult(null);
      setProgress(0);
    }
  }, [config.id]);

  // Cleanup worker on unmount
  useEffect(() => {
    return () => { workerRef.current?.terminate(); };
  }, []);

  const toggleStrategy = (s: Strategy) => {
    setSelectedStrategies(prev =>
      prev.includes(s) ? prev.filter(x => x !== s) : [...prev, s]
    );
  };

  const runSim = () => {
    if (selectedStrategies.length === 0) return;
    setRunning(true);
    setProgress(0);
    setResult(null);

    workerRef.current?.terminate();

    const worker = new MonteCarloWorker();
    workerRef.current = worker;

    worker.onmessage = (e: MessageEvent) => {
      const { type, data } = e.data;
      if (type === "progress") {
        setProgress(Math.round((data.completed / data.total) * 100));
      } else if (type === "result") {
        setResult(data as MassiveSimResult);
        setProgress(100);
        setRunning(false);
        worker.terminate();
        workerRef.current = null;
      }
    };

    worker.onerror = () => {
      setRunning(false);
      worker.terminate();
      workerRef.current = null;
    };

    worker.postMessage({
      type: "run_monte_carlo",
      job: {
        stats: stats.map(s => ({
          number: s.number, frequency: s.frequency, percentage: s.percentage,
          lastSeen: s.lastSeen, trend: s.trend, status: s.status,
          recentFreq: s.recentFreq, stdDevIntervals: s.stdDev,
          momentum: s.momentum, cycleScore: s.cycleScore,
        })),
        config,
        draws,
        simConfig: {
          iterations,
          strategies: selectedStrategies,
          config,
          compareWithRandom: true,
        },
      },
    });
  };

  // Build chart data for hit distribution comparison
  const hitDistChart = result
    ? (() => {
        const allHits = new Set<number>();
        result.performances.forEach(p => {
          Object.keys(p.hitDistribution).forEach(h => allHits.add(Number(h)));
        });
        const sorted = [...allHits].sort((a, b) => a - b).filter(h => h >= Math.max(0, config.pick - 5));

        return sorted.map(hits => {
          const row: any = { hits: `${hits} acertos` };
          result.performances.forEach(p => {
            row[p.label] = Math.round((p.hitDistribution[hits] || 0) / p.totalGames * 10000) / 100;
          });
          return row;
        });
      })()
    : [];

  return (
    <Card className="bg-card/80 backdrop-blur border-border">
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-foreground">
          <Rocket className="w-5 h-5 text-primary" />
          Simulador Massivo Monte Carlo
        </CardTitle>
        <p className="text-xs text-muted-foreground">
          Laboratório estatístico — teste estratégias com centenas de milhares de simulações e projete resultados anuais
        </p>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Iteration selector */}
        <div>
          <label className="text-xs font-medium text-muted-foreground mb-2 block">Iterações</label>
          <div className="flex gap-2">
            {ITERATION_OPTIONS.map(opt => (
              <button
                key={opt.value}
                onClick={() => setIterations(opt.value)}
                className={`text-xs font-mono px-3 py-1.5 rounded-md border transition-all ${
                  iterations === opt.value
                    ? "border-primary text-primary bg-primary/10"
                    : "border-border text-muted-foreground hover:text-foreground"
                }`}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </div>

        {/* Strategy selector */}
        <div>
          <label className="text-xs font-medium text-muted-foreground mb-2 block">Estratégias para testar</label>
          <div className="flex flex-wrap gap-1.5">
            {STRATEGIES.map(s => (
              <button
                key={s.id}
                onClick={() => toggleStrategy(s.id)}
                className={`text-xs px-2.5 py-1 rounded-md border transition-all ${
                  selectedStrategies.includes(s.id)
                    ? "border-primary text-primary bg-primary/10"
                    : "border-border text-muted-foreground hover:text-foreground"
                }`}
              >
                {s.label}
              </button>
            ))}
          </div>
        </div>

        {/* Run button */}
        <Button
          onClick={runSim}
          disabled={running || selectedStrategies.length === 0}
          className="w-full gap-2"
        >
          {running ? (
            <>
              <Zap className="w-4 h-4 animate-pulse" />
              Simulando {iterations.toLocaleString()} iterações...
            </>
          ) : (
            <>
              <Play className="w-4 h-4" />
              Executar {iterations.toLocaleString()} Simulações
            </>
          )}
        </Button>

        {/* Progress */}
        {running && (
          <div className="space-y-1">
            <Progress value={progress} className="h-2" />
            <p className="text-xs text-muted-foreground text-right">{Math.round(progress)}%</p>
          </div>
        )}

        {/* Results */}
        <AnimatePresence>
          {result && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              className="space-y-5"
            >
              {/* Summary bar */}
              <div className="flex items-center gap-3 text-xs text-muted-foreground p-2 rounded-lg bg-muted/30 border border-border">
                <CheckCircle2 className="w-4 h-4 text-primary" />
                <span>{result.totalIterations.toLocaleString()} simulações em {result.elapsedMs}ms</span>
                <span>•</span>
                <span>{result.performances.length} estratégias comparadas</span>
              </div>

              {/* Strategy ranking */}
              <div>
                <h4 className="text-xs font-semibold text-foreground mb-3 flex items-center gap-1.5">
                  <Trophy className="w-3.5 h-3.5 text-primary" /> Ranking de Estratégias
                </h4>
                <div className="space-y-2">
                  {result.performances.map((p, idx) => (
                    <div
                      key={p.strategy}
                      className="flex items-center gap-3 p-3 rounded-lg bg-muted/20 border border-border"
                    >
                      <span className="text-lg font-bold font-mono text-primary w-7 text-right">
                        #{idx + 1}
                      </span>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-semibold text-foreground">{p.label}</span>
                          {idx === 0 && <Badge variant="default" className="text-[10px]">Melhor</Badge>}
                        </div>
                        <div className="flex gap-3 mt-1 text-[11px] text-muted-foreground">
                          <span>Média: <strong className="text-foreground">{p.avgHits}</strong></span>
                          <span>Melhor: <strong className="text-foreground">{p.bestHit}</strong></span>
                          <span>4+: <strong className="text-foreground">{p.hitRate4Plus}%</strong></span>
                          <span>EV: <strong className="text-primary">{p.expectedValue}x</strong></span>
                        </div>
                      </div>
                      <div className="text-right hidden sm:block">
                        <p className="text-[10px] text-muted-foreground">Consistência</p>
                        <p className="text-sm font-mono font-bold text-foreground">
                          {(p.consistency * 100).toFixed(0)}%
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Hit distribution chart */}
              {hitDistChart.length > 0 && (
                <div>
                  <h4 className="text-xs font-semibold text-foreground mb-3 flex items-center gap-1.5">
                    <BarChart3 className="w-3.5 h-3.5 text-primary" /> Distribuição de Acertos (%)
                  </h4>
                  <div className="h-56">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={hitDistChart}>
                        <XAxis dataKey="hits" tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 10 }} />
                        <YAxis tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 10 }} unit="%" />
                        <Tooltip
                          contentStyle={{
                            background: "hsl(var(--card))",
                            border: "1px solid hsl(var(--border))",
                            borderRadius: 8,
                            color: "hsl(var(--foreground))",
                            fontSize: 12,
                          }}
                        />
                        <Legend />
                        {result.performances.map((p, i) => (
                          <Bar
                            key={p.strategy}
                            dataKey={p.label}
                            fill={STRATEGY_COLORS[i % STRATEGY_COLORS.length]}
                            fillOpacity={0.8}
                            radius={[2, 2, 0, 0]}
                          />
                        ))}
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              )}

              {/* Convergence chart */}
              {result.convergenceData.length > 0 && (
                <div>
                  <h4 className="text-xs font-semibold text-foreground mb-3 flex items-center gap-1.5">
                    <TrendingUp className="w-3.5 h-3.5 text-primary" /> Convergência da Média
                  </h4>
                  <div className="h-48">
                    <ResponsiveContainer width="100%" height="100%">
                      <LineChart data={(() => {
                        // Pivot convergence data by iteration
                        const byIter = new Map<number, any>();
                        result.convergenceData.forEach(d => {
                          if (!byIter.has(d.iteration)) byIter.set(d.iteration, { iteration: d.iteration });
                          byIter.get(d.iteration)![d.strategy] = d.avgHits;
                        });
                        return [...byIter.values()].sort((a, b) => a.iteration - b.iteration);
                      })()}>
                        <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                        <XAxis dataKey="iteration" tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 10 }} />
                        <YAxis tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 10 }} />
                        <Tooltip
                          contentStyle={{
                            background: "hsl(var(--card))",
                            border: "1px solid hsl(var(--border))",
                            borderRadius: 8,
                            color: "hsl(var(--foreground))",
                            fontSize: 12,
                          }}
                        />
                        <Legend />
                        {result.performances.map((p, i) => (
                          <Line
                            key={p.strategy}
                            type="monotone"
                            dataKey={p.label}
                            stroke={STRATEGY_COLORS[i % STRATEGY_COLORS.length]}
                            strokeWidth={2}
                            dot={false}
                          />
                        ))}
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              )}

              {/* Yearly projection */}
              <div>
                <h4 className="text-xs font-semibold text-foreground mb-3 flex items-center gap-1.5">
                  <Calendar className="w-3.5 h-3.5 text-primary" /> Projeção Anual (156 jogos/ano)
                </h4>
                <div className="overflow-x-auto">
                  <table className="w-full text-xs">
                    <thead>
                      <tr className="border-b border-border text-muted-foreground">
                        <th className="text-left p-2">Estratégia</th>
                        <th className="text-right p-2">4+ acertos</th>
                        <th className="text-right p-2">5+ acertos</th>
                        <th className="text-right p-2">Acerto Total</th>
                        <th className="text-right p-2">ROI</th>
                      </tr>
                    </thead>
                    <tbody>
                      {result.yearlyProjection.map(y => (
                        <tr key={y.strategy} className="border-b border-border/50">
                          <td className="p-2 font-medium text-foreground">{y.strategy}</td>
                          <td className="p-2 text-right font-mono text-foreground">{y.expectedHits4Plus}</td>
                          <td className="p-2 text-right font-mono text-foreground">{y.expectedHits5Plus}</td>
                          <td className="p-2 text-right font-mono text-muted-foreground">{y.expectedFullHits}</td>
                          <td className="p-2 text-right font-mono text-primary font-bold">{y.roi}x</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </CardContent>
    </Card>
  );
}

import { useState, useMemo, useEffect, useRef } from "react";
import DOMPurify from "dompurify";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Progress } from "@/components/ui/progress";
import {
  Search, Brain, Loader2, TrendingUp, TrendingDown, BarChart3, Zap, Target,
  GitBranch, Layers, RefreshCw, AlertTriangle, Sparkles, ArrowRight, Clock, Hash,
} from "lucide-react";
import { toast } from "sonner";
import { DrawResult, LotteryConfig } from "@/data/lotteries";
import { NumberStats } from "@/engine/statistics";
import { detectPatterns, PatternReport } from "@/engine/pattern-detector";
import { generatePatternAnalysis } from "@/engine/native-analysis";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, RadarChart, Radar, PolarGrid, PolarAngleAxis, PolarRadiusAxis,
  ScatterChart, Scatter, ZAxis, LineChart, Line,
} from "recharts";

interface Props {
  config: LotteryConfig;
  draws: DrawResult[];
  stats: NumberStats[];
}

const DRAW_OPTIONS = [
  { label: "Últimos 50", value: 50 },
  { label: "Últimos 100", value: 100 },
  { label: "Últimos 200", value: 200 },
  { label: "Últimos 500", value: 500 },
  { label: "Todo histórico", value: 99999 },
];

const PIE_COLORS = ["hsl(145, 72%, 42%)", "hsl(195, 95%, 48%)", "hsl(48, 100%, 52%)", "hsl(265, 75%, 58%)", "hsl(0, 72%, 55%)", "hsl(180, 85%, 48%)", "hsl(30, 90%, 55%)", "hsl(320, 70%, 55%)"];

export function PatternDetectorPanel({ config, draws, stats }: Props) {
  const [drawCount, setDrawCount] = useState("200");
  const [report, setReport] = useState<PatternReport | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState("");
  const [loadingAi, setLoadingAi] = useState(false);
  const [detecting, setDetecting] = useState(false);

  const prevId = useRef(config.id);
  useEffect(() => {
    if (prevId.current !== config.id) {
      prevId.current = config.id;
      setReport(null);
      setAiAnalysis("");
    }
  }, [config.id]);

  const handleDetect = () => {
    setDetecting(true);
    setAiAnalysis("");
    setTimeout(() => {
      try {
        const result = detectPatterns(draws, stats, config, parseInt(drawCount));
        setReport(result);
        toast.success("Padrões detectados com sucesso!");
      } catch (e) {
        toast.error("Erro na detecção de padrões");
        console.error(e);
      } finally {
        setDetecting(false);
      }
    }, 50);
  };

  const handleAiAnalysis = async () => {
    if (!report) return;
    setLoadingAi(true);
    try {
      await new Promise(r => setTimeout(r, 200));
      const analysis = generatePatternAnalysis(report, config, parseInt(drawCount));
      setAiAnalysis(analysis);
    } catch (e: any) {
      toast.error(e.message || "Erro na análise");
    } finally {
      setLoadingAi(false);
    }
  };

  const parityChartData = useMemo(() => {
    if (!report) return [];
    return report.parityPatterns.slice(0, 6).map(p => ({
      name: `${p.evens}P/${p.odds}I`, value: p.count, percentage: p.percentage,
    }));
  }, [report]);

  const sumChartData = useMemo(() => {
    if (!report) return [];
    return report.sumPatterns.map(s => ({ faixa: s.rangeLabel, concursos: s.count, percentual: s.percentage }));
  }, [report]);

  const spatialRadarData = useMemo(() => {
    if (!report) return [];
    return report.spatialDistribution.sectors.map(s => ({
      setor: s.label, media: s.avgCount,
      fullMark: Math.ceil(config.pick / report.spatialDistribution.sectors.length * 2),
    }));
  }, [report, config.pick]);

  const transitionChartData = useMemo(() => {
    if (!report) return [];
    return report.transitionAnalysis.repeatDistribution.map(r => ({
      repeats: `${r.repeats} repet.`, count: r.count, percentage: r.percentage,
    }));
  }, [report]);

  const momentumChartData = useMemo(() => {
    if (!report) return [];
    return report.frequencyTrends.slice(0, 20).map(f => ({
      name: String(f.number).padStart(2, "0"),
      momentum: f.momentum,
      score: f.score,
      fill: f.momentum > 0 ? "hsl(145, 72%, 42%)" : "hsl(0, 72%, 55%)",
    }));
  }, [report]);

  const cycleScatterData = useMemo(() => {
    if (!report) return [];
    return report.cycleDetection.slice(0, 25).map(c => ({
      name: String(c.number).padStart(2, "0"),
      x: c.avgCycleLength,
      y: c.currentDelay,
      z: c.confidence * 100,
      status: c.status,
    }));
  }, [report]);

  return (
    <Card className="border-primary/20 bg-card/80 backdrop-blur">
      <CardHeader>
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-lg bg-primary/10">
            <Search className="h-6 w-6 text-primary" />
          </div>
          <div className="flex-1">
            <CardTitle className="text-xl text-foreground">Detector de Padrões v2.1</CardTitle>
            <CardDescription>
              Ciclos, transições, coocorrência, primos, Fibonacci e clusterização
            </CardDescription>
          </div>
          {report && (
            <div className="flex items-center gap-2">
              <div className="text-right hidden sm:block">
                <p className="text-[10px] text-muted-foreground">Score Geral</p>
                <p className="text-lg font-bold text-primary">{report.summary.overallScore}%</p>
              </div>
            </div>
          )}
          <Badge variant="outline" className="text-[10px] border-primary/30 text-primary hidden sm:inline-flex">
            DEEP ANALYSIS
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-5">
        {/* Controls */}
        <div className="flex gap-3 items-end">
          <div className="flex-1 space-y-1.5">
            <label className="text-xs text-muted-foreground font-medium">Concursos para análise</label>
            <Select value={drawCount} onValueChange={setDrawCount}>
              <SelectTrigger className="bg-muted/50"><SelectValue /></SelectTrigger>
              <SelectContent>
                {DRAW_OPTIONS.map(o => (
                  <SelectItem key={o.value} value={String(o.value)}>{o.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <Button onClick={handleDetect} disabled={detecting || draws.length === 0} className="bg-primary text-primary-foreground">
            {detecting ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Search className="h-4 w-4 mr-2" />}
            Detectar Padrões
          </Button>
        </div>

        {report && (
          <Tabs defaultValue="overview" className="space-y-4">
            <TabsList className="bg-muted/50 flex-wrap h-auto gap-1">
              <TabsTrigger value="overview" className="text-xs"><Zap className="h-3 w-3 mr-1" />Resumo</TabsTrigger>
              <TabsTrigger value="charts" className="text-xs"><BarChart3 className="h-3 w-3 mr-1" />Gráficos</TabsTrigger>
              <TabsTrigger value="trends" className="text-xs"><TrendingUp className="h-3 w-3 mr-1" />Tendências</TabsTrigger>
              <TabsTrigger value="transitions" className="text-xs"><RefreshCw className="h-3 w-3 mr-1" />Transições</TabsTrigger>
              <TabsTrigger value="clusters" className="text-xs"><Layers className="h-3 w-3 mr-1" />Clusters</TabsTrigger>
              <TabsTrigger value="cycles" className="text-xs"><GitBranch className="h-3 w-3 mr-1" />Ciclos</TabsTrigger>
              <TabsTrigger value="rare" className="text-xs"><AlertTriangle className="h-3 w-3 mr-1" />Raros</TabsTrigger>
              <TabsTrigger value="ai" className="text-xs"><Brain className="h-3 w-3 mr-1" />IA</TabsTrigger>
            </TabsList>

            {/* Overview */}
            <TabsContent value="overview" className="space-y-4">
              {/* Score bar */}
              <div className="bg-muted/20 rounded-lg p-4 border border-border/30">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-semibold text-foreground flex items-center gap-2">
                    <Sparkles className="h-4 w-4 text-primary" /> Qualidade da Análise
                  </span>
                  <span className="text-sm font-bold text-primary">{report.summary.overallScore}/100</span>
                </div>
                <Progress value={report.summary.overallScore} className="h-2" />
                <p className="text-[10px] text-muted-foreground mt-1">
                  Baseado na quantidade de dados, regularidade de ciclos, clusters e equilíbrio espacial
                </p>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {[
                  { label: "Paridade dominante", value: report.summary.mostCommonParity, sub: `Desvio: ${report.summary.parityDeviation}%` },
                  { label: "Soma média", value: report.summary.avgSum, sub: `Mediana: ${report.summary.medianSum}` },
                  { label: "Consecutivos médios", value: report.summary.avgConsecutives },
                  { label: "Equilíbrio espacial", value: `${report.spatialDistribution.balance}%`, primary: true },
                ].map((item, i) => (
                  <div key={i} className="bg-muted/30 rounded-lg p-3 text-center">
                    <p className="text-xs text-muted-foreground">{item.label}</p>
                    <p className={`text-lg font-bold ${item.primary ? "text-primary" : "text-foreground"}`}>{item.value}</p>
                    {item.sub && <p className="text-[10px] text-muted-foreground">{item.sub}</p>}
                  </div>
                ))}
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
                <div className="bg-muted/30 rounded-lg p-3 text-center">
                  <p className="text-xs text-muted-foreground">Repetições médias</p>
                  <p className="text-lg font-bold text-primary">{report.summary.avgRepeatsBetweenDraws}</p>
                </div>
                <div className="bg-muted/30 rounded-lg p-3 text-center">
                  <p className="text-xs text-muted-foreground">Clusters</p>
                  <p className="text-lg font-bold text-foreground">{report.numberClusters.length}</p>
                </div>
                <div className="bg-muted/30 rounded-lg p-3 text-center">
                  <p className="text-xs text-muted-foreground">Padrões raros</p>
                  <p className="text-lg font-bold text-foreground">{report.rarePatterns.length}</p>
                </div>
                <div className="bg-muted/30 rounded-lg p-3 text-center">
                  <p className="text-xs text-muted-foreground">Coocorrências</p>
                  <p className="text-lg font-bold text-foreground">{report.cooccurrenceMatrix.length}</p>
                </div>
                <div className="bg-muted/30 rounded-lg p-3 text-center">
                  <p className="text-xs text-muted-foreground">% Primos</p>
                  <p className="text-lg font-bold text-foreground">{report.summary.primeRatio}%</p>
                </div>
              </div>

              {/* Trending numbers */}
              <div className="grid sm:grid-cols-2 gap-4">
                <NumberBadgeGrid title="Em Alta" icon={<TrendingUp className="h-4 w-4 text-green-400" />} numbers={report.summary.trendingUp} colorClass="bg-green-500/15 text-green-400" />
                <NumberBadgeGrid title="Em Queda" icon={<TrendingDown className="h-4 w-4 text-red-400" />} numbers={report.summary.trendingDown} colorClass="bg-red-500/15 text-red-400" />
              </div>
              <div className="grid sm:grid-cols-2 gap-4">
                <NumberBadgeGrid title="Mais Consistentes" icon={<Target className="h-4 w-4 text-primary" />} numbers={report.summary.mostConsistent} colorClass="bg-primary/15 text-primary" />
                <NumberBadgeGrid title="Atrasadas (Overdue)" icon={<Clock className="h-4 w-4 text-yellow-400" />} numbers={report.summary.overdueNumbers} colorClass="bg-yellow-500/15 text-yellow-400" />
              </div>

              {report.hotStreaks.length > 0 && (
                <div className="bg-muted/20 rounded-lg p-3 border border-border/30">
                  <h4 className="text-sm font-semibold text-foreground mb-2">🔥 Maiores Sequências Quentes</h4>
                  <div className="flex flex-wrap gap-2 text-xs">
                    {report.hotStreaks.slice(0, 8).map((h, i) => (
                      <Badge key={i} variant="outline" className="border-orange-400/30 text-orange-400">
                        Nº {String(h.number).padStart(2, "0")}: {h.streakLength}x seguidos
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
            </TabsContent>

            {/* Charts */}
            <TabsContent value="charts" className="space-y-5">
              <div className="grid lg:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <h4 className="text-sm font-semibold text-foreground">Distribuição Par/Ímpar</h4>
                  <div className="h-56">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={parityChartData} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={40} outerRadius={80} label={({ name, percentage }) => `${name} ${percentage}%`}>
                          {parityChartData.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                        </Pie>
                        <Tooltip contentStyle={{ background: "hsl(var(--card))", border: "1px solid hsl(var(--border))", borderRadius: "8px", color: "hsl(var(--foreground))" }} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                </div>
                <div className="space-y-2">
                  <h4 className="text-sm font-semibold text-foreground">Distribuição de Soma</h4>
                  <div className="h-56">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={sumChartData}>
                        <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                        <XAxis dataKey="faixa" stroke="hsl(var(--muted-foreground))" tick={{ fontSize: 10 }} />
                        <YAxis stroke="hsl(var(--muted-foreground))" tick={{ fontSize: 10 }} />
                        <Tooltip contentStyle={{ background: "hsl(var(--card))", border: "1px solid hsl(var(--border))", borderRadius: "8px", color: "hsl(var(--foreground))" }} />
                        <Bar dataKey="concursos" fill="hsl(195, 95%, 48%)" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              </div>

              {/* Momentum chart */}
              <div className="space-y-2">
                <h4 className="text-sm font-semibold text-foreground flex items-center gap-2">
                  <TrendingUp className="h-4 w-4 text-primary" /> Momentum das Top 20 Dezenas
                </h4>
                <div className="h-56">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={momentumChartData}>
                      <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                      <XAxis dataKey="name" stroke="hsl(var(--muted-foreground))" tick={{ fontSize: 10 }} />
                      <YAxis stroke="hsl(var(--muted-foreground))" tick={{ fontSize: 10 }} />
                      <Tooltip
                        contentStyle={{ background: "hsl(var(--card))", border: "1px solid hsl(var(--border))", borderRadius: "8px", color: "hsl(var(--foreground))" }}
                        formatter={(value: number, name: string) => [value, name === "momentum" ? "Momentum" : "Score"]}
                      />
                      <Bar dataKey="momentum" radius={[4, 4, 0, 0]}>
                        {momentumChartData.map((entry, i) => (
                          <Cell key={i} fill={entry.fill} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="grid lg:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <h4 className="text-sm font-semibold text-foreground">Distribuição Espacial (Radar)</h4>
                  <div className="h-64">
                    <ResponsiveContainer width="100%" height="100%">
                      <RadarChart data={spatialRadarData}>
                        <PolarGrid stroke="hsl(var(--border))" />
                        <PolarAngleAxis dataKey="setor" tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 11 }} />
                        <PolarRadiusAxis tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 10 }} />
                        <Radar name="Média" dataKey="media" stroke="hsl(145, 72%, 42%)" fill="hsl(145, 72%, 42%)" fillOpacity={0.3} />
                      </RadarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
                <div className="space-y-2">
                  <h4 className="text-sm font-semibold text-foreground">Padrão de Consecutivos</h4>
                  <div className="flex flex-wrap gap-3">
                    {report.consecutivePatterns.map(c => (
                      <div key={c.consecutiveCount} className="bg-muted/30 rounded-lg p-3 text-center min-w-[100px]">
                        <p className="text-xs text-muted-foreground">{c.consecutiveCount} consec.</p>
                        <p className="text-lg font-bold text-foreground">{c.occurrences}x</p>
                        <p className="text-xs text-muted-foreground">{c.percentage}%</p>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </TabsContent>

            {/* Trends with score */}
            <TabsContent value="trends" className="space-y-3">
              <div className="overflow-x-auto">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b border-border text-muted-foreground">
                      <th className="text-left p-2">Nº</th>
                      <th className="text-center p-2">Últ. 10</th>
                      <th className="text-center p-2">Últ. 30</th>
                      <th className="text-center p-2">Últ. 100</th>
                      <th className="text-center p-2">Total</th>
                      <th className="text-center p-2">Tendência</th>
                      <th className="text-center p-2">Momentum</th>
                      <th className="text-center p-2">Score</th>
                    </tr>
                  </thead>
                  <tbody>
                    {report.frequencyTrends.slice(0, 30).map(f => (
                      <tr key={f.number} className="border-b border-border/30">
                        <td className="p-2 font-bold text-foreground">{String(f.number).padStart(2, "0")}</td>
                        <td className="p-2 text-center font-mono">{f.last10Freq}</td>
                        <td className="p-2 text-center font-mono">{f.last30Freq}</td>
                        <td className="p-2 text-center font-mono">{f.last100Freq}</td>
                        <td className="p-2 text-center font-mono text-muted-foreground">{f.totalFreq}</td>
                        <td className="p-2 text-center">
                          <Badge variant="outline" className={`text-[10px] ${
                            f.trendDirection === "up" ? "text-green-400 border-green-400/30" :
                            f.trendDirection === "down" ? "text-red-400 border-red-400/30" :
                            "text-muted-foreground"
                          }`}>
                            {f.trendDirection === "up" ? "↑ Alta" : f.trendDirection === "down" ? "↓ Queda" : "→ Estável"}
                          </Badge>
                        </td>
                        <td className={`p-2 text-center font-mono font-bold ${f.momentum > 0 ? "text-green-400" : f.momentum < 0 ? "text-red-400" : "text-muted-foreground"}`}>
                          {f.momentum > 0 ? "+" : ""}{f.momentum}
                        </td>
                        <td className="p-2 text-center">
                          <div className="flex items-center justify-center gap-1">
                            <div className="w-10 h-1.5 bg-muted/50 rounded-full overflow-hidden">
