import { createContext, useContext, useEffect, useState, ReactNode } from "react";
import { Session, User } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

export type PlanType = "free" | "premium" | "professional" | "lifetime";

interface Profile {
  id: string;
  email: string | null;
  full_name: string | null;
  avatar_url: string | null;
  plan: PlanType;
  theme_preference: string;
  language: string;
  timezone: string;
  currency_format: string;
  blocked: boolean;
  created_at: string;
}

interface AuthContextType {
  session: Session | null;
  user: User | null;
  profile: Profile | null;
  loading: boolean;
  isAdmin: boolean;
  isSuperAdmin: boolean;
  userRole: string;
  isTrialExpired: boolean;
  trialDaysLeft: number;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | null>(null);

const FULL_ACCESS_EMAIL = "etcsuporte889@gmail.com";

function isFullAccessEmail(email?: string | null) {
  return email?.toLowerCase() === FULL_ACCESS_EMAIL;
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isSuperAdmin, setIsSuperAdmin] = useState(false);
  const [userRole, setUserRole] = useState<string>("user");

  const fetchProfile = async (userId: string, email?: string | null) => {
    const { data } = await supabase
      .from("profiles")
      .select("*")
      .eq("id", userId)
      .single();
    if (data) {
      setProfile(isFullAccessEmail(email) ? { ...(data as Profile), plan: "lifetime", blocked: false } : data as Profile);
    }
  };

  const checkAdmin = async (userId: string, email?: string | null) => {
    if (isFullAccessEmail(email)) {
      setIsAdmin(true);
      setIsSuperAdmin(true);
      setUserRole("super_admin");
      return;
    }

    const { data } = await supabase
      .from("user_roles")
      .select("role")
      .eq("user_id", userId)
      .in("role", ["admin", "super_admin"]);
    const roles = (data || []).map((r: any) => r.role as string);
    setIsAdmin(roles.includes("admin") || roles.includes("super_admin"));
    setIsSuperAdmin(roles.includes("super_admin"));
    setUserRole(roles.includes("super_admin") ? "super_admin" : roles.includes("admin") ? "admin" : roles[0] || "user");
  };

  const syncSubscription = async (accessToken: string) => {
    try {
      const { data } = await supabase.functions.invoke("check-subscription", {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      if (data?.plan) {
        setProfile(prev => prev ? { ...prev, plan: data.plan as PlanType } : prev);
      }
    } catch (e) {
      console.error("Error checking subscription:", e);
    }
  };

  useEffect(() => {
    const authStorageKey = `sb-${import.meta.env.VITE_SUPABASE_PROJECT_ID}-auth-token`;
    let initialLoad = true;

    const loadUserData = async (userId: string, accessToken?: string, email?: string | null) => {
      await Promise.all([
        fetchProfile(userId, email),
        checkAdmin(userId, email),
        ...(accessToken ? [syncSubscription(accessToken)] : []),
      ]);
    };

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (_event, session) => {
        setSession(session);
        if (session?.user) {
          if (!initialLoad) {
            await loadUserData(session.user.id, undefined, session.user.email);
          }
        } else {
          setProfile(null);
          setIsAdmin(false);
          setIsSuperAdmin(false);
          setUserRole("user");
        }
        if (!initialLoad) setLoading(false);
      }
    );

    supabase.auth.getSession()
      .then(async ({ data: { session }, error }) => {
        if (error) {
          const message = error.message.toLowerCase();
          const isInvalidRefreshToken =
            message.includes("invalid refresh token") ||
            message.includes("refresh token not found");

          if (isInvalidRefreshToken) {
            localStorage.removeItem(authStorageKey);
          }

          setSession(null);
          setProfile(null);
          return;
        }

        setSession(session);
        if (session?.user) {
          await loadUserData(session.user.id, session.access_token, session.user.email);
        }
      })
      .catch(() => {
        localStorage.removeItem(authStorageKey);
        setSession(null);
        setProfile(null);
      })
      .finally(() => {
        initialLoad = false;
        setLoading(false);
      });

    return () => subscription.unsubscribe();
  }, []);

  const signOut = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setProfile(null);
  };

  const TRIAL_DAYS = 7;

  const trialDaysLeft = (() => {
    if (!profile?.created_at || profile.plan !== "free") return TRIAL_DAYS;
    const created = new Date(profile.created_at).getTime();
    const now = Date.now();
    const elapsed = Math.floor((now - created) / (1000 * 60 * 60 * 24));
    return Math.max(0, TRIAL_DAYS - elapsed);
  })();

  const isTrialExpired = !isAdmin && !isSuperAdmin && profile?.plan === "free" && trialDaysLeft <= 0;

  return (
    <AuthContext.Provider value={{ session, user: session?.user ?? null, profile, loading, isAdmin, isSuperAdmin, userRole, isTrialExpired, trialDaysLeft, signOut }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be within AuthProvider");
  return ctx;
}

import { createContext, useContext, useState, useMemo, useCallback, ReactNode } from "react";
import { LOTTERIES, DrawResult } from "@/data/lotteries";
import { computeFrequencyStats, computeSumDistribution, NumberStats } from "@/engine/statistics";
import { useLotteryDraws, DrawResultWithPrizes } from "@/hooks/useLotteryDraws";

interface LotteryContextType {
  selectedLottery: string;
  setSelectedLottery: (id: string) => void;
  config: (typeof LOTTERIES)[0];
  draws: DrawResult[];
  drawsWithPrizes: DrawResultWithPrizes[];
  loading: boolean;
  syncing: boolean;
  count: number;
  syncDraws: () => void;
  syncAllLotteries: () => void;
  addDraw: (draw: DrawResult) => void;
  stats: NumberStats[];
  sumData: ReturnType<typeof computeSumDistribution>;
}

const LotteryContext = createContext<LotteryContextType | null>(null);

export function LotteryProvider({ children }: { children: ReactNode }) {
  const [selectedLottery, setSelectedLottery] = useState("megasena");
  const config = LOTTERIES.find(l => l.id === selectedLottery)!;
  const { draws, drawsWithPrizes, loading, syncing, count, syncDraws, syncAllLotteries, addDraw } = useLotteryDraws(selectedLottery);
  const stats = useMemo(() => computeFrequencyStats(draws, config.numbers), [draws, config.numbers]);
  const sumData = useMemo(() => computeSumDistribution(draws), [draws]);

  return (
    <LotteryContext.Provider value={{
      selectedLottery, setSelectedLottery: useCallback((id: string) => setSelectedLottery(id), []),
      config, draws, drawsWithPrizes, loading, syncing, count, syncDraws, syncAllLotteries, addDraw, stats, sumData,
    }}>
      {children}
    </LotteryContext.Provider>
  );
}

export function useLotteryContext() {
  const ctx = useContext(LotteryContext);
  if (!ctx) throw new Error("useLotteryContext must be within LotteryProvider");
  return ctx;
}

import { createContext, useContext, useState, useCallback, ReactNode } from "react";

export interface MarkedBet {
  numbers: number[];
  label: string;
}

interface SelectedBetsContextType {
  markedBets: MarkedBet[];
  toggleBet: (bet: MarkedBet) => void;
  clearMarked: () => void;
  isBetMarked: (numbers: number[]) => boolean;
  checkResults: BulkCheckResult[] | null;
  setCheckResults: (results: BulkCheckResult[] | null) => void;
}

export interface BulkCheckResult {
  numbers: number[];
  label: string;
  draws: { concurso: number; date: string; hits: number; matched: number[] }[];
  avgHits: number;
  bestHit: number;
  prizeHits: number;
}

const SelectedBetsContext = createContext<SelectedBetsContextType | null>(null);

export function SelectedBetsProvider({ children }: { children: ReactNode }) {
  const [markedBets, setMarkedBets] = useState<MarkedBet[]>([]);
  const [checkResults, setCheckResults] = useState<BulkCheckResult[] | null>(null);

  const toggleBet = useCallback((bet: MarkedBet) => {
    setMarkedBets(prev => {
      const key = bet.numbers.join(",");
      const exists = prev.some(b => b.numbers.join(",") === key);
      if (exists) return prev.filter(b => b.numbers.join(",") !== key);
      return [...prev, bet];
    });
    setCheckResults(null);
  }, []);

  const isBetMarked = useCallback((numbers: number[]) => {
    const key = numbers.join(",");
    return markedBets.some(b => b.numbers.join(",") === key);
  }, [markedBets]);

  const clearMarked = useCallback(() => {
    setMarkedBets([]);
    setCheckResults(null);
  }, []);

  return (
    <SelectedBetsContext.Provider value={{ markedBets, toggleBet, clearMarked, isBetMarked, checkResults, setCheckResults }}>
      {children}
    </SelectedBetsContext.Provider>
  );
}

export function useSelectedBets() {
  const ctx = useContext(SelectedBetsContext);
  if (!ctx) throw new Error("useSelectedBets must be within SelectedBetsProvider");
  return ctx;
}

