export function generateMassiveSimAnalysis(
  topGames: any[],
  patternInsights: any,
  distributionSummary: any,
  config: LotteryConfig,
  totalGenerated: number,
  totalEvaluated: number
): string {
  const numFreq: Record<number, number> = {};
  topGames.forEach((g: any) => {
    (g.numbers || []).forEach((n: number) => { numFreq[n] = (numFreq[n] || 0) + 1; });
  });

  const topNumbers = Object.entries(numFreq).sort((a, b) => b[1] - a[1]).slice(0, 15);
  const bottomNumbers = Object.entries(numFreq).sort((a, b) => a[1] - b[1]).slice(0, 10);

  let md = `## 🚀 Análise da Simulação Massiva — ${config.name}\n\n`;
  md += `**${totalGenerated.toLocaleString()}** jogos gerados → **${totalEvaluated.toLocaleString()}** avaliados → **Top ${topGames.length}** selecionados\n\n`;

  md += `### 🎯 Dezenas "Must-Have"\n`;
  topNumbers.forEach(([n, freq]) => {
    const pct = (freq / topGames.length * 100).toFixed(0);
    const bar = Number(pct) >= 80 ? '🔥' : Number(pct) >= 60 ? '✅' : '➖';
    md += `- ${bar} **${String(n).padStart(2, '0')}**: ${pct}% dos top jogos (${freq}x)\n`;
  });
  md += `\n`;

  md += `### ❌ Dezenas "Tóxicas"\n`;
  bottomNumbers.forEach(([n, freq]) => {
    md += `- **${String(n).padStart(2, '0')}**: apenas ${freq}x nos top jogos\n`;
  });
  md += `\n`;

  if (distributionSummary) {
    md += `### 📊 Distribuição dos Top Jogos\n`;
    md += `- Soma média: **${distributionSummary.avgSum?.toFixed(0) || 'N/A'}**\n`;
    md += `- Ratio par/ímpar: **${((distributionSummary.avgEvenRatio || 0) * 100).toFixed(0)}%** pares\n`;
    md += `- Spread médio: **${distributionSummary.avgSpread?.toFixed(0) || 'N/A'}**\n`;
    md += `- Taxa de premiação: **${(distributionSummary.avgPrizeRate || 0).toFixed(2)}%**\n`;
    md += `- Melhor acerto geral: **${distributionSummary.bestHitOverall || 0}** de ${config.pick}\n\n`;
  }

  if (patternInsights) {
    md += `### 🔍 Padrões Detectados\n`;
    if (patternInsights.dominantParity) md += `- Paridade dominante: **${patternInsights.dominantParity}**\n`;
    if (patternInsights.sumTrend) md += `- Tendência de soma: **${patternInsights.sumTrend}**\n`;
    md += `\n`;
  }

  md += `### 🏆 Top 5 Jogos\n`;
  topGames.slice(0, 5).forEach((g: any, i: number) => {
    md += `${i + 1}. [${(g.numbers || []).map((n: number) => String(n).padStart(2, '0')).join(', ')}] — Score: **${g.score?.toFixed(0) || 'N/A'}**\n`;
  });
  md += `\n`;

  md += `### 💡 Como Usar\n`;
  md += `- Priorize dezenas "must-have" na construção de apostas\n`;
  md += `- Evite concentrar dezenas "tóxicas" no mesmo jogo\n`;
  md += `- Os top 5 jogos representam as combinações mais otimizadas\n`;
  md += `- Use como base para fechamentos matemáticos\n\n`;
  md += `---\n*Análise gerada pelo motor estatístico nativo v2.0.*`;
  return md;
}

// ═══════════════════════════════════════════
// AUTONOMOUS AI ANALYSIS (text report + 10 games)
// ═══════════════════════════════════════════
export function generateAutonomousAnalysis(
  report: any,
  config: LotteryConfig
): string {
  const topRankings = report.rankings?.slice(0, 25) || [];
  const patterns = report.patterns || [];
  const shifts = report.shifts?.slice(0, 15) || [];
  const entropy = report.entropyAnalysis || {};
  const chiSquare = report.chiSquareResult || {};
  const gaps = report.gapAnalysis?.slice(0, 15) || [];
  const markov = report.markovTransitions?.slice(0, 15) || [];
  const cooccurrences = report.topCooccurrences?.slice(0, 10) || [];
  const rules = getLotteryRules(config.id);

  const tierS = topRankings.filter((r: any) => r.compositeScore >= 80);
  const tierA = topRankings.filter((r: any) => r.compositeScore >= 60 && r.compositeScore < 80);

  let md = `## 🧠 Análise Autônoma Profunda — ${config.name}\n\n`;
  md += `Score de confiança: **${report.confidenceScore || 0}/100**\n`;
  md += `Metodologia: Frequência + Markov + Entropia + Chi² + Ciclos + Co-ocorrência\n\n`;

  // Rankings
  md += `### 🏅 Ranking de Dezenas\n`;
  if (tierS.length > 0) {
    md += `**Tier S** (score ≥80): ${tierS.map((r: any) => `**${String(r.number).padStart(2, '0')}** (${r.compositeScore})`).join(', ')}\n\n`;
  }
  if (tierA.length > 0) {
    md += `**Tier A** (score ≥60): ${tierA.map((r: any) => `**${String(r.number).padStart(2, '0')}** (${r.compositeScore})`).join(', ')}\n\n`;
  }

  // Entropy
  if (entropy.entropy !== undefined) {
    const entropyPct = ((entropy.entropy / Math.log2(config.numbers)) * 100).toFixed(1);
    md += `### 📐 Análise de Entropia\nEntropia: **${entropy.entropy?.toFixed(3) || 'N/A'}** (${entropyPct}% da máxima)\n`;
    md += `${Number(entropyPct) > 95 ? '✅ Distribuição muito uniforme' : Number(entropyPct) > 85 ? '⚠️ Leve concentração' : '❌ Concentração significativa'}\n\n`;
  }

  // Chi-square
  if (chiSquare.chiSquare !== undefined) {
    md += `### 📊 Teste Chi-Quadrado\nχ² = **${chiSquare.chiSquare?.toFixed(2) || 'N/A'}** | p-valor = **${chiSquare.pValue?.toFixed(4) || 'N/A'}**\n`;
    md += `${(chiSquare.pValue || 1) > 0.05 ? '✅ Sem evidência de não-aleatoriedade' : '⚠️ Distribuição não-uniforme detectada'}\n\n`;
  }

  // Gaps
  if (gaps.length > 0) {
    const overdue = gaps.filter((g: any) => g.currentGap > g.avgGap * 1.3);
    if (overdue.length > 0) {
      md += `### ⏰ Dezenas Atrasadas\n${overdue.map((g: any) => `**${String(g.number).padStart(2, '0')}** (gap: ${g.currentGap}, média: ${g.avgGap.toFixed(1)})`).join(', ')}\n\n`;
    }
  }

  // Markov
  if (markov.length > 0) {
    md += `### 🔗 Transições de Markov\nTop transições: ${markov.slice(0, 8).map((m: any) => `${String(m.from).padStart(2, '0')}→${String(m.to).padStart(2, '0')} (${m.count}x)`).join(', ')}\n\n`;
  }

  // Patterns
  if (patterns.length > 0) {
    md += `### 🔍 Padrões Detectados\n`;
    patterns.slice(0, 5).forEach((p: any) => {
      md += `- **${p.type || p.name}**: ${p.description || `Score: ${p.score || 'N/A'}`}\n`;
    });
    md += `\n`;
  }

  // Shifts
  if (shifts.length > 0) {
    md += `### 📈 Mudanças de Regime\n`;
    const risingShifts = shifts.filter((s: any) => s.direction === 'up' || s.shift > 0);
    const fallingShifts = shifts.filter((s: any) => s.direction === 'down' || s.shift < 0);
    if (risingShifts.length > 0) md += `Em alta: ${risingShifts.slice(0, 5).map((s: any) => `**${String(s.number).padStart(2, '0')}**`).join(', ')}\n`;
    if (fallingShifts.length > 0) md += `Em queda: ${fallingShifts.slice(0, 5).map((s: any) => `**${String(s.number).padStart(2, '0')}**`).join(', ')}\n`;
    md += `\n`;
  }

  md += `### 💡 Recomendações Estratégicas\n`;
  md += `- Priorize dezenas Tier S e A como núcleo das apostas\n`;
  md += `- Inclua 1-2 dezenas atrasadas (overdue) para diversificação\n`;
  md += `- Respeite transições de Markov para sequências prováveis\n`;
  md += `- Mantenha soma dentro da faixa ideal: **${rules.idealSumRange?.[0] || '?'}–${rules.idealSumRange?.[1] || '?'}**\n`;
  md += `- Paridade ideal: **${rules.idealParityRange?.[0] || '?'}–${rules.idealParityRange?.[1] || '?'}** pares\n`;
  if (config.id === 'lotofacil') {
    md += `- Moldura/Centro ideal: **${rules.idealFrameRange?.[0] || 8}–${rules.idealFrameRange?.[1] || 11}** na moldura\n`;
  }
  md += `\n`;

  // Generate 10 games using enhanced strategy
  const allRanked = topRankings.map((r: any) => r.number);
  const overdueList = gaps.filter((g: any) => g.isOverdue || g.currentGap > (g.avgGap || 5) * 1.2).map((g: any) => g.number);
  const markovFavored = markov.slice(0, 10).map((m: any) => m.to);

  md += `## 🎯 10 JOGOS OTIMIZADOS\n\n`;

  const strategies = [
    { name: 'Conservador', desc: 'Núcleo Tier S/A, alta frequência' },
    { name: 'Conservador', desc: 'Frequência + co-ocorrência forte' },
    { name: 'Conservador', desc: 'Estabilidade máxima, soma ideal' },
    { name: 'Equilibrado', desc: 'Mix frequência + Markov + ciclos' },
    { name: 'Equilibrado', desc: 'Transições de Markov + momentum' },
    { name: 'Equilibrado', desc: 'Dispersão otimizada + primos' },
    { name: 'Agressivo', desc: 'Overdue + momentum positivo' },
    { name: 'Agressivo', desc: 'Anti-padrão + dezenas em alta' },
    { name: 'Contrário', desc: 'Dezenas frias com ciclo favorável' },
    { name: 'Cobertura Máxima', desc: 'Máxima dispersão + Fibonacci' },
  ];

  const seenGames = new Set<string>();
  let gameIndex = 0;

  for (let g = 0; g < 10; g++) {
    let pool = [...allRanked];

    // Enrich pool based on strategy
    if (g >= 3 && g < 6) {
      markovFavored.forEach((n: number) => { if (!pool.includes(n)) pool.push(n); });
    }
    if (g >= 6 && g < 8) {
      overdueList.forEach((n: number) => { if (!pool.includes(n)) pool.push(n); });
    }
    if (g === 8) {
      // Contrarian: reverse ranking
      pool = [...allRanked].reverse();
      overdueList.forEach((n: number) => { if (!pool.includes(n)) pool.unshift(n); });
    }
    if (g === 9) {
      // Max coverage: spread across all ranges
      const rangeSize = Math.ceil(config.numbers / 5);
      pool = [];
      for (let r = 0; r < 5; r++) {
        const lo = r * rangeSize + 1;
        const hi = Math.min((r + 1) * rangeSize, config.numbers);
        const rangeNums = allRanked.filter((n: number) => n >= lo && n <= hi);
        pool.push(...rangeNums.slice(0, Math.ceil(config.pick / 5) + 1));
      }
      // Add Fibonacci
      FIBONACCI.forEach(n => { if (n <= config.numbers && !pool.includes(n)) pool.push(n); });
    }

    // Ensure enough in pool
    if (pool.length < config.pick) {
      for (let n = 1; n <= config.numbers; n++) {
        if (!pool.includes(n)) pool.push(n);
        if (pool.length >= config.pick * 2) break;
      }
    }

    // Generate game with bias
    let bestGame: number[] | null = null;
    let bestScore = -1;

    for (let attempt = 0; attempt < 200; attempt++) {
      const game: number[] = [];
      const available = [...pool];

      while (game.length < config.pick && available.length > 0) {
        const bias = g < 3 ? 0.75 : g < 6 ? 0.5 : 0.3;
        const idx = Math.random() < bias
          ? Math.floor(Math.random() * Math.min(available.length, Math.ceil(config.pick * 1.5)))
          : Math.floor(Math.random() * available.length);
        const safeIdx = Math.min(idx, available.length - 1);
        const num = available[safeIdx];
        if (!game.includes(num) && num >= 1 && num <= config.numbers) {
          game.push(num);
        }
        available.splice(safeIdx, 1);
      }

      while (game.length < config.pick) {
        const n = Math.floor(Math.random() * config.numbers) + 1;
        if (!game.includes(n)) game.push(n);
      }

      game.sort((a, b) => a - b);
      const key = game.join(',');
      if (seenGames.has(key)) continue;

      // Score this game
      let score = 0;
      // Sum score
      score += sumScore(game, config.id) * 25;
      // Parity
      const evens = game.filter(n => n % 2 === 0).length;
      const idealParity = rules.idealParityRange || [Math.floor(config.pick * 0.4), Math.ceil(config.pick * 0.6)];
      if (evens >= idealParity[0] && evens <= idealParity[1]) score += 20;
      else score += 10;
      // Consecutive
      const maxSeq = maxConsecutive(game);
      if (maxSeq <= (rules.maxRecommendedSequence || 3)) score += 15;
      else score += 5;
      // Frame balance (Lotofácil)
      score += frameBalance(game, config.id) * 10;
      // Ranking position bonus
      const rankedSet = new Set(allRanked.slice(0, config.pick + 5));
      const inRanked = game.filter(n => rankedSet.has(n)).length;
      score += (inRanked / config.pick) * 20;
      // Prime/Fib bonus
      score += primeRatio(game) * 5;
      score += fibRatio(game) * 5;

      if (score > bestScore) {
        bestScore = score;
        bestGame = game;
      }
    }

    if (!bestGame) continue;
    const key = bestGame.join(',');
    if (seenGames.has(key)) continue;
    seenGames.add(key);

    gameIndex++;
    const confidence = Math.round(Math.min(95, bestScore));
    const nums = bestGame.map(n => String(n).padStart(2, '0')).join(', ');
    const sum = bestGame.reduce((a, b) => a + b, 0);
    const evens = bestGame.filter(n => n % 2 === 0).length;
    const primes = bestGame.filter(n => PRIMES.has(n)).length;

    md += `GAME_START\nJogo ${gameIndex} - ${strategies[g].name} (Confiança: ${confidence}/100)\n`;
    md += `Estratégia: ${strategies[g].desc}\n`;
    md += `Dezenas: ${nums}\n`;
    md += `Soma: ${sum} | Pares: ${evens} | Primos: ${primes}\n`;
    md += `GAME_END\n\n`;
  }

  md += `---\n*Análise gerada pelo motor estatístico nativo v2.0 com Markov + Entropia + Co-ocorrência.*`;
  return md;
}

// ═══════════════════════════════════════════
// NATIVE BET GENERATION v2.0 (enhanced)
// ═══════════════════════════════════════════
export function generateNativeBets(
  stats: NumberStats[],
  config: LotteryConfig,
  draws: DrawResult[],
  count: number
): { bets: number[][]; analysis: string; quality: { avgScore: number; scores: number[]; grade: string } } {
  const { entropy } = (function() {
    if (draws.length < 10) return { entropy: 50 };
    const recentSams = draws.slice(0, 10).map(d => d.numbers.reduce((a, b) => a + b, 0));
    const avgSum = recentSams.reduce((a, b) => a + b, 0) / 10;
    const variance = recentSams.reduce((a, b) => a + Math.pow(b - avgSum, 2), 0) / 10;
    return { entropy: Math.min(100, Math.sqrt(variance) * 2) };
  })();

  const rules = getLotteryRules(config.id);
  const minNum = config.name === "Super Sete" ? 0 : 1;
  const allNums = Array.from({ length: config.numbers - minNum + 1 }, (_, i) => i + minNum);

  // Frequency maps
  const freq50: Record<number, number> = {};
  const freq30: Record<number, number> = {};
  const freq10: Record<number, number> = {};
  const lastSeen: Record<number, number> = {};
  for (const n of allNums) { freq50[n] = 0; freq30[n] = 0; freq10[n] = 0; lastSeen[n] = 999; }

  draws.forEach((d, i) => {
    d.numbers.forEach(n => {
      if (i < 50) freq50[n] = (freq50[n] || 0) + 1;
      if (i < 30) freq30[n] = (freq30[n] || 0) + 1;
      if (i < 10) freq10[n] = (freq10[n] || 0) + 1;
      if (lastSeen[n] === 999) lastSeen[n] = i;
    });
  });

  // Build Markov matrix
  const markov = buildMarkovMatrix(draws.slice(0, 100), config.numbers);
  const lastDraw = draws[0]?.numbers || [];
  const markovSuccessors = getMarkovSuccessors(lastDraw, markov, 20);
  const markovSet = new Set(markovSuccessors.map(m => m.number));

  // Build co-occurrence map
  const cooccMap = buildCooccurrenceMap(draws, 100);

  // Repeat analysis
  const [minRepeat, maxRepeat] = idealRepeatCount(config);

  // Composite score per number (enhanced)
  const compositeScores = allNums.map(n => {
    const s = stats.find(st => st.number === n);
    let score = 0;
    // Historical frequency (normalized)
    score += (freq50[n] || 0) * 1.5;
    // Recent frequency (higher weight)
    score += (freq30[n] || 0) * 2;
    score += (freq10[n] || 0) * 3;
    // Trend
    if (s?.trend && s.trend > 0) score += s.trend * 8;
    // Cycle (overdue bonus)
    if (s?.cycleScore && s.cycleScore > 1) score += (s.cycleScore - 1) * 12;
    // Recency
    if (lastSeen[n] <= 2) score += 6;
    else if (lastSeen[n] <= 5) score += 3;
    // Momentum
    if (s?.momentum && s.momentum > 0) score += s.momentum * 0.005;
    // Markov boost
    if (markovSet.has(n)) {
      const ms = markovSuccessors.find(m => m.number === n);
      score += (ms?.score || 0) * 0.5;
    }
    // Prime/Fibonacci subtle boost
    if (PRIMES.has(n)) score += 1;
    if (FIBONACCI.has(n)) score += 0.5;

    return { number: n, score };
  }).sort((a, b) => b.score - a.score);

  const bets: number[][] = [];
  const scores: number[] = [];
  const seenKeys = new Set<string>();

  // Strategy profiles for diverse generation
  const strategyProfiles = [
    { name: 'Conservadora', topBias: 0.80, poolMult: 1.8, markovWeight: 0.2, cycleWeight: 0.1 },
    { name: 'Conservadora', topBias: 0.75, poolMult: 2.0, markovWeight: 0.3, cycleWeight: 0.1 },
    { name: 'Equilibrada', topBias: 0.55, poolMult: 2.5, markovWeight: 0.4, cycleWeight: 0.3 },
    { name: 'Equilibrada', topBias: 0.50, poolMult: 2.8, markovWeight: 0.3, cycleWeight: 0.4 },
    { name: 'Agressiva', topBias: 0.35, poolMult: 3.0, markovWeight: 0.2, cycleWeight: 0.6 },
    { name: 'Markov', topBias: 0.40, poolMult: 2.0, markovWeight: 0.7, cycleWeight: 0.2 },
    { name: 'Ciclos', topBias: 0.30, poolMult: 3.5, markovWeight: 0.1, cycleWeight: 0.8 },
    { name: 'Anti-Padrão', topBias: 0.25, poolMult: 4.0, markovWeight: 0.3, cycleWeight: 0.3 },
    { name: 'Cobertura', topBias: 0.45, poolMult: 3.0, markovWeight: 0.2, cycleWeight: 0.2 },
    { name: 'Momentum', topBias: 0.60, poolMult: 2.2, markovWeight: 0.4, cycleWeight: 0.1 },
  ];

  // Entropia bias: Se entropia for alta (>60), favorece estratégias de Cobertura e Anti-Padrão
  if (entropy > 60) {
    strategyProfiles.unshift(
      { name: 'Cobertura (Entropia)', topBias: 0.40, poolMult: 3.5, markovWeight: 0.1, cycleWeight: 0.1 },
      { name: 'Anti-Padrão (Entropia)', topBias: 0.20, poolMult: 4.5, markovWeight: 0.2, cycleWeight: 0.2 }
    );
  }

  for (let attempt = 0; attempt < 3000 && bets.length < count; attempt++) {
    const profileIdx = bets.length % strategyProfiles.length;
    const profile = strategyProfiles[Math.min(profileIdx, strategyProfiles.length - 1)];

    // Build weighted pool
    const poolSize = Math.min(allNums.length, Math.ceil(config.pick * profile.poolMult));
    const pool = compositeScores.slice(0, poolSize).map(c => ({
      number: c.number,
      weight: c.score * (1 - profile.markovWeight - profile.cycleWeight)
        + (markovSet.has(c.number) ? (markovSuccessors.find(m => m.number === c.number)?.score || 0) * profile.markovWeight : 0)
        + ((stats.find(s => s.number === c.number)?.cycleScore || 0) > 1 ? 10 * profile.cycleWeight : 0),
    }));

    // Add some random numbers for aggressive/coverage strategies
    if (profile.topBias < 0.4) {
      const extras = allNums
        .filter(n => !pool.find(p => p.number === n))
        .sort(() => Math.random() - 0.5)
        .slice(0, Math.floor(config.pick * 0.3));
      extras.forEach(n => pool.push({ number: n, weight: 2 }));
    }

    // Weighted sampling
    const candidate: number[] = [];
    const remaining = [...pool];

    while (candidate.length < config.pick && remaining.length > 0) {
      const totalW = remaining.reduce((s, p) => s + Math.max(0.1, p.weight), 0);
      let r = Math.random() * totalW;
      let idx = 0;
      for (; idx < remaining.length; idx++) {
        r -= Math.max(0.1, remaining[idx].weight);
        if (r <= 0) break;
      }
      idx = Math.min(idx, remaining.length - 1);
      candidate.push(remaining[idx].number);
      remaining.splice(idx, 1);
    }

    // Fill if needed
    while (candidate.length < config.pick) {
      const n = Math.floor(Math.random() * config.numbers) + minNum;
      if (!candidate.includes(n)) candidate.push(n);
    }

    candidate.sort((a, b) => a - b);
    if (new Set(candidate).size !== config.pick) continue;
    const key = candidate.join(',');
    if (seenKeys.has(key)) continue;

    // ═══ VALIDATION FILTERS ═══
    // Sum range
    const sum = candidate.reduce((a, b) => a + b, 0);
    if (rules.idealSumRange) {
      const [lo, hi] = rules.idealSumRange;
      const margin = (hi - lo) * 0.2;
      if (sum < lo - margin || sum > hi + margin) continue;
    }

    // Parity
    const evens = candidate.filter(n => n % 2 === 0).length;
    if (rules.idealParityRange) {
      const [minP, maxP] = rules.idealParityRange;
      if (evens < minP - 1 || evens > maxP + 1) continue;
    }

    // Consecutive sequences
    const mSeq = maxConsecutive(candidate);
    if (mSeq > (rules.maxRecommendedSequence || 3)) continue;

    // Repeat from last draw
    if (lastDraw.length > 0) {
      const repeats = countRepeats(candidate, lastDraw);
      if (repeats < Math.max(0, minRepeat - 1) || repeats > maxRepeat + 1) continue;
    }

    // Frame balance (Lotofácil)
    if (config.id === 'lotofacil') {
      const frameCount = candidate.filter(n => LOTOFACIL_FRAME.has(n)).length;
      const idealFrame = rules.idealFrameRange || [8, 11];
      if (frameCount < idealFrame[0] - 1 || frameCount > idealFrame[1] + 1) continue;
    }

    // Diversity from existing bets
    const isDiverse = bets.every(b => {
      const overlap = candidate.filter(n => b.includes(n)).length;
      return config.pick - overlap >= Math.max(2, Math.floor(config.pick * 0.15));
    });
    if (!isDiverse) continue;

    // ═══ SCORING (0-100) ═══
    let score = 0;

    // Sum adherence (0-20)
    score += sumScore(candidate, config.id) * 20;

    // Parity balance (0-15)
    if (rules.idealParityRange) {
      const [minP, maxP] = rules.idealParityRange;
      if (evens >= minP && evens <= maxP) score += 15;
      else score += 8;
    } else {
      score += (1 - Math.abs(evens / config.pick - 0.5) * 2) * 15;
    }

    // Frequency bonus (0-15)
    const avgFreq = candidate.reduce((s, n) => s + (freq30[n] || 0), 0) / config.pick;
    score += Math.min(15, avgFreq * 1.5);

    // Recent frequency (0-10)
    const avgRecent = candidate.reduce((s, n) => s + (freq10[n] || 0), 0) / config.pick;
    score += Math.min(10, avgRecent * 2.5);

    // Markov alignment (0-10)
    const markovCount = candidate.filter(n => markovSet.has(n)).length;
    score += Math.min(10, (markovCount / config.pick) * 15);

    // Co-occurrence boost (0-10)
    const coocBoost = cooccurrenceBoost(candidate, cooccMap);
    score += Math.min(10, coocBoost * 0.3);

    // Cycle/overdue (0-5)
    const overdueCount = candidate.filter(n => {
      const s = stats.find(st => st.number === n);
      return s && s.cycleScore > 1.2;
    }).length;
    score += Math.min(5, overdueCount * 2);

    // Consecutive penalty
    if (mSeq > 2) score -= (mSeq - 2) * 3;

    // Repeat from last draw bonus (0-5)
    if (lastDraw.length > 0) {
      const repeats = countRepeats(candidate, lastDraw);
      if (repeats >= minRepeat && repeats <= maxRepeat) score += 5;
    }

    // Frame bonus for Lotofácil (0-5)
    if (config.id === 'lotofacil') {
      score += (frameBalance(candidate, config.id) - 0.7) / 0.3 * 5;
    }

    // Prime ratio (0-3)
    const pr = primeRatio(candidate);
    if (pr >= 0.2 && pr <= 0.5) score += 3;

    score = Math.max(0, Math.min(100, Math.round(score)));
    seenKeys.add(key);
    bets.push(candidate);
    scores.push(score);
  }

  const avgScore = scores.length > 0 ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
  const grade = avgScore >= 90 ? "S" : avgScore >= 80 ? "A" : avgScore >= 70 ? "B" : avgScore >= 60 ? "C" : "D";

  // Build rich analysis text
  const strategyNames = ['Conservadora', 'Equilibrada', 'Agressiva', 'Markov', 'Ciclos', 'Anti-Padrão', 'Cobertura', 'Momentum'];
  let analysis = `⚡ **${bets.length} apostas** geradas pelo motor nativo v2.0\n`;
  analysis += `📊 Metodologia: Frequência + Markov + Ciclos + Co-ocorrência + Entropia\n\n`;

  bets.forEach((b, i) => {
    const profIdx = i % strategyProfiles.length;
    const strat = strategyProfiles[profIdx]?.name || 'Mista';
    const sum = b.reduce((a, c) => a + c, 0);
    const evens = b.filter(n => n % 2 === 0).length;
    const repeats = lastDraw.length > 0 ? countRepeats(b, lastDraw) : 0;
    const primes = b.filter(n => PRIMES.has(n)).length;
    analysis += `**Jogo ${i + 1}** (${strat}): Soma=${sum}, P=${evens}/I=${config.pick - evens}, Rep=${repeats}, Primos=${primes}, Score=${scores[i]}\n`;
  });

  return { bets, analysis, quality: { avgScore, scores, grade } };
}

// ═══════════════════════════════════════════
// NATIVE BET IMPROVEMENT v2.0
// ═══════════════════════════════════════════
export function generateNativeImprovements(
  betsToImprove: { numbers: number[]; label?: string; avgHits?: number; bestHit?: number; prizeHits?: number }[],
  stats: NumberStats[],
  config: LotteryConfig,
  draws: DrawResult[]
): { original: number[]; suggested: number[]; reason: string; expectedGain: string }[] {
  const rules = getLotteryRules(config.id);
  const minNum = config.name === "Super Sete" ? 0 : 1;
  const allNums = Array.from({ length: config.numbers - minNum + 1 }, (_, i) => i + minNum);

  const freq10: Record<number, number> = {};
  for (const n of allNums) freq10[n] = 0;
  draws.slice(0, 10).forEach(d => d.numbers.forEach(n => { freq10[n] = (freq10[n] || 0) + 1; }));

  const markov = buildMarkovMatrix(draws.slice(0, 50), config.numbers);
  const lastDraw = draws[0]?.numbers || [];
  const markovSuccessors = getMarkovSuccessors(lastDraw, markov, 15);
  const markovSet = new Set(markovSuccessors.map(m => m.number));

  return betsToImprove.map(bet => {
    const nums = [...bet.numbers];
    const statsMap = new Map(stats.map(s => [s.number, s]));

    // Score each number in bet
    const scored = nums.map(n => {
      const s = statsMap.get(n);
      let score = (s?.frequency || 0) * 0.2 + (s?.recentFreq || 0) * 0.3 + (s?.cycleScore || 0) * 0.2 + (freq10[n] || 0) * 2;
      if (markovSet.has(n)) score += 3;
      if (s?.trend && s.trend > 0) score += s.trend * 2;
      return { number: n, score };
    }).sort((a, b) => a.score - b.score);

    const replaceCount = Math.min(3, Math.max(1, Math.floor(nums.length * 0.15)));
    const toRemove = scored.slice(0, replaceCount).map(s => s.number);
    const remaining = nums.filter(n => !toRemove.includes(n));

    // Find replacements considering balance
    const mid = config.numbers / 2;
    const evenCount = remaining.filter(r => r % 2 === 0).length;
    const highCount = remaining.filter(r => r > mid).length;
    const idealEvens = rules.idealParityRange ? rules.idealParityRange[0] : Math.round(config.pick / 2);
    const needEven = idealEvens - evenCount;
    const needHigh = Math.round(config.pick / 2) - highCount;

    const candidates = allNums
      .filter(n => !remaining.includes(n))
      .map(n => {
        const s = statsMap.get(n);
        let score = (s?.frequency || 0) * 0.2 + (s?.recentFreq || 0) * 0.3 + (freq10[n] || 0) * 2;
        if (markovSet.has(n)) score += 5;
        if (s?.trend && s.trend > 0) score += s.trend * 3;
        if (s?.cycleScore && s.cycleScore > 1.2) score += 4;
        if (needEven > 0 && n % 2 === 0) score += 8;
        if (needEven < 0 && n % 2 !== 0) score += 8;
        if (needHigh > 0 && n > mid) score += 6;
        if (needHigh < 0 && n <= mid) score += 6;
        return { number: n, score };
      })
      .sort((a, b) => b.score - a.score);

    const toAdd = candidates.slice(0, replaceCount).map(c => c.number);
    const suggested = [...remaining, ...toAdd].sort((a, b) => a - b);

    const reasons: string[] = [];
    toRemove.forEach(n => {
      const s = statsMap.get(n);
      if (s && s.status === 'cold') reasons.push(`${String(n).padStart(2, '0')} (frio) removido`);
      else if (s && s.trend && s.trend < 0) reasons.push(`${String(n).padStart(2, '0')} (queda) removido`);
    });
    toAdd.forEach(n => {
      if (markovSet.has(n)) reasons.push(`${String(n).padStart(2, '0')} adicionado (Markov)`);
      else {
        const s = statsMap.get(n);
        if (s && s.status === 'hot') reasons.push(`${String(n).padStart(2, '0')} adicionado (quente)`);
        else if (s && s.cycleScore && s.cycleScore > 1.2) reasons.push(`${String(n).padStart(2, '0')} adicionado (overdue)`);
      }
    });

    const oldSum = nums.reduce((a, b) => a + b, 0);
    const newSum = suggested.reduce((a, b) => a + b, 0);
    const oldSumScore = sumScore(nums, config.id);
    const newSumScore = sumScore(suggested, config.id);
    const gain = Math.round((newSumScore - oldSumScore) * 100);

    if (reasons.length === 0) reasons.push('Números estatisticamente fracos substituídos por candidatos mais fortes');

    return {
      original: bet.numbers,
      suggested,
      reason: reasons.join('. ') + '.',
      expectedGain: gain > 0 ? `+${gain}% soma otimizada` : "+10-20% estimado",
    };
  });
}

import { DrawResult, LotteryConfig } from "@/data/lotteries";

export interface NumberStats {
  number: number;
  frequency: number;
  percentage: number;
  lastSeen: number; // draws ago
  recentFreq: number; // last 30 draws
  status: "hot" | "cold" | "normal";
  // Advanced metrics
  avgGap: number; // average gap between appearances
  maxGap: number; // longest streak without appearing
  stdDev: number; // standard deviation of gaps
  trend: number; // positive = trending up, negative = trending down
  momentum: number; // acceleration of frequency change
  consecutivePairs: number; // how often appears with neighbor ±1
  cycleScore: number; // how "due" the number is based on its cycle
  expectedAppearance: number; // calculated next expected concurso (relative)
  hotStreak: number; // current consecutive appearances
}


export function computeFrequencyStats(draws: DrawResult[], totalNumbers: number): NumberStats[] {
  const freq = new Array(totalNumbers + 1).fill(0);
  const lastSeen = new Array(totalNumbers + 1).fill(draws.length);
  const recentFreq = new Array(totalNumbers + 1).fill(0);
  const recent = 30;

  // Track all appearance positions for gap analysis
  const appearances: number[][] = Array.from({ length: totalNumbers + 1 }, () => []);

  // Track frequency in windows for trend analysis
  const window1Freq = new Array(totalNumbers + 1).fill(0); // last 10
  const window2Freq = new Array(totalNumbers + 1).fill(0); // 11-30
  const window3Freq = new Array(totalNumbers + 1).fill(0); // 31-60

  // Consecutive pair tracking
  const consecutivePairCount = new Array(totalNumbers + 1).fill(0);

  const streak = new Array(totalNumbers + 1).fill(0);
  let lastDrawNumbers = draws[0]?.numbers || [];

  draws.filter(d => d && Array.isArray(d.numbers)).forEach((draw, i) => {

    const numSet = new Set(draw.numbers);
    draw.numbers.forEach(n => {
      if (n < 1 || n > totalNumbers || !appearances[n]) return;
      freq[n]++;
      if (i < lastSeen[n]) lastSeen[n] = i;
      if (i < recent) recentFreq[n]++;
      appearances[n].push(i);

      if (i < 10) window1Freq[n]++;
      else if (i < 30) window2Freq[n]++;
      else if (i < 60) window3Freq[n]++;

      // Check consecutive neighbors
      if (numSet.has(n - 1) || numSet.has(n + 1)) {
        consecutivePairCount[n]++;
      }
    });
  });

  const total = draws.length;
  const avgFreq = total > 0 ? draws[0].numbers.length / totalNumbers : 0;

  const stats: NumberStats[] = [];
  for (let n = 1; n <= totalNumbers; n++) {
    const pct = total > 0 ? (freq[n] / total) * 100 : 0;
    const avgPct = avgFreq * 100;
    let status: "hot" | "cold" | "normal" = "normal";
    if (pct > avgPct * 1.15) status = "hot";
    else if (pct < avgPct * 0.85) status = "cold";

    // Gap analysis
    const gaps: number[] = [];
    const sorted = appearances[n].sort((a, b) => a - b);
    for (let i = 1; i < sorted.length; i++) {
      gaps.push(sorted[i] - sorted[i - 1]);
    }
    if (sorted.length > 0) {
      gaps.unshift(sorted[0]); // gap from start
    }

    const avgGap = gaps.length > 0 ? gaps.reduce((a, b) => a + b, 0) / gaps.length : total;
    const maxGap = gaps.length > 0 ? Math.max(...gaps) : total;
    const mean = avgGap;
    const stdDev = gaps.length > 1
      ? Math.sqrt(gaps.reduce((sum, g) => sum + (g - mean) ** 2, 0) / gaps.length)
      : 0;

    // Trend: compare recent windows (positive = heating up)
    const w1Rate = window1Freq[n] / 10;
    const w2Rate = window2Freq[n] / 20;
    const w3Rate = window3Freq[n] / 30;
    const trend = (w1Rate - w2Rate) * 50;
    const momentum = (w1Rate - w2Rate) - (w2Rate - w3Rate); // acceleration

    // Cycle score: how overdue is this number?
    const expectedGap = freq[n] > 0 ? total / freq[n] : total;
    const cycleScore = expectedGap > 0 ? lastSeen[n] / expectedGap : 0;

    stats.push({
      number: n,
      frequency: freq[n],
      percentage: pct,
      lastSeen: lastSeen[n],
      recentFreq: recentFreq[n],
      status,
      avgGap,
      maxGap,
      stdDev,
      trend,
      momentum: momentum * 100,
      consecutivePairs: consecutivePairCount[n],
      cycleScore,
      expectedAppearance: Math.round(avgGap - lastSeen[n]),
      hotStreak: draws.slice(0, 5).filter(d => d.numbers.includes(n)).length,
    });
  }

  return stats;
}

export interface PairStats {
  even: number;
  odd: number;
}

export function computeParityDistribution(draws: DrawResult[]): PairStats[] {
  return draws.slice(0, 50).map(d => ({
    even: d.numbers.filter(n => n % 2 === 0).length,
    odd: d.numbers.filter(n => n % 2 !== 0).length,
  }));
}

export function computeSumDistribution(draws: DrawResult[]): { concurso: number; sum: number }[] {
  return draws.slice(0, 50).map(d => ({
    concurso: d.concurso,
    sum: d.numbers.reduce((a, b) => a + b, 0),
  }));
}

export function generateSmartBet(stats: NumberStats[], pick: number): number[] {
  const weighted = stats.map(s => ({
    number: s.number,
    weight:
      (s.status === "hot" ? 3 : s.status === "cold" ? 1 : 2) +
      s.trend * 0.5 +
      s.cycleScore * 2 +
      (s.momentum > 0 ? s.momentum * 0.3 : 0),
  })).map(w => ({ ...w, weight: Math.max(0.1, w.weight) }));

  const selected: number[] = [];
  const pool = [...weighted];

  while (selected.length < pick && pool.length > 0) {
    const totalWeight = pool.reduce((a, b) => a + b.weight, 0);
    let r = Math.random() * totalWeight;
    for (let i = 0; i < pool.length; i++) {
      r -= pool[i].weight;
      if (r <= 0) {
        selected.push(pool[i].number);
        pool.splice(i, 1);
        break;
      }
    }
  }

  return selected.sort((a, b) => a - b);
}

export function runMonteCarloSimulation(
  config: LotteryConfig,
  stats: NumberStats[],
  iterations: number = 10000
): { number: number; wins: number }[] {
  const winCount = new Array(config.numbers + 1).fill(0);

  for (let i = 0; i < iterations; i++) {
    const bet = generateSmartBet(stats, config.pick);
    const draw: number[] = [];
    while (draw.length < config.pick) {
      const n = Math.floor(Math.random() * config.numbers) + 1;
      if (!draw.includes(n)) draw.push(n);
    }
    bet.forEach(n => {
      if (draw.includes(n)) winCount[n]++;
    });
  }

  return Array.from({ length: config.numbers }, (_, i) => ({
    number: i + 1,
    wins: winCount[i + 1],
  })).sort((a, b) => b.wins - a.wins);
}

import { NumberStats } from "@/features/statistics/engine";
import { DrawResult, LotteryConfig } from "@/data/lotteries";
import { generateByStrategy, Strategy, STRATEGIES } from "@/features/statistics/strategies";

// ═══════════════════════════════════════════════════════
// Motor de Backtesting Automático
// Testa estratégias contra resultados históricos reais
// ═══════════════════════════════════════════════════════

export interface BacktestResult {
  strategy: Strategy;
  label: string;
  totalTests: number;
  hitDistribution: Record<number, number>;
  avgHits: number;
  bestHit: number;
  winRate: number; // % with minimum prize hits
  profit: number; // estimated ROI
  consistency: number; // 0-1
  streaks: { bestWin: number; worstLoss: number };
  equityCurve: { x: number; y: number }[];
  maxDrawdown: number;
  recoveryFactor: number;
  sharpeRatio: number;
  globalScore: number;
}

export interface BacktestConfig {
  strategies: Strategy[];
  testWindow: number; // how many recent draws to test
  betsPerDraw: number; // bets generated per draw
  minPrizeHits: number; // minimum hits to count as "win"
}

export function runBacktest(
  stats: NumberStats[],
  config: LotteryConfig,
  draws: DrawResult[],
  btConfig: BacktestConfig
): BacktestResult[] {
  const sorted = [...draws].sort((a, b) => a.concurso - b.concurso);
  const testDraws = sorted.slice(-btConfig.testWindow);

  const results: BacktestResult[] = [];

  // Costs and prizes per lottery
  const costs: Record<string, number> = {
    lotofacil: 3.0, megasena: 5.0, quina: 2.5, lotomania: 3.0,
    duplasena: 2.5, timemania: 3.5, diadesorte: 2.5, supersete: 2.5,
  };
  const costPerGame = costs[config.id] || 3.0;

  const prizeMap: Record<string, Record<number, number>> = {
    megasena: { 4: 1200, 5: 45000, 6: 35000000 },
    lotofacil: { 11: 6, 12: 12, 13: 30, 14: 1500, 15: 1500000 },
    quina: { 2: 3, 3: 120, 4: 8000, 5: 2000000 },
    lotomania: { 0: 300000, 15: 10, 16: 40, 17: 200, 18: 2500, 19: 50000, 20: 5000000 },
    duplasena: { 3: 6, 4: 150, 5: 5000, 6: 1000000 },
    timemania: { 3: 3.5, 4: 10.5, 5: 100, 6: 25000, 7: 3000000 },
    diadesorte: { 4: 5, 5: 25, 6: 2500, 7: 500000 },
    supersete: { 3: 5, 4: 50, 5: 1000, 6: 15000, 7: 2000000 },
  };
  const prizeWeights = prizeMap[config.id] || { [config.pick - 2]: 50, [config.pick - 1]: 5000, [config.pick]: 500000 };

  for (const strategy of btConfig.strategies) {
    const stratInfo = STRATEGIES.find(s => s.id === strategy);
    const hitDist: Record<number, number> = {};
    for (let i = 0; i <= config.pick; i++) hitDist[i] = 0;

    let totalHits = 0;
    let bestHit = 0;
    let wins = 0;
    let currentStreak = 0;
    let bestWinStreak = 0;
    let currentLossStreak = 0;
    let worstLossStreak = 0;

    let balance = 0;
    const equityCurve: { x: number; y: number }[] = [{ x: 0, y: 0 }];
    let peak = 0;
    let maxDrawdown = 0;
    const dailyReturns: number[] = [];

    const totalTests = testDraws.length * btConfig.betsPerDraw;

    testDraws.forEach((draw, drawIdx) => {
      let drawPrize = 0;
      let drawCost = btConfig.betsPerDraw * costPerGame;

      for (let b = 0; b < btConfig.betsPerDraw; b++) {
        const bet = generateByStrategy(strategy, stats, config);
        const drawSet = new Set(draw.numbers);
        const hits = bet.filter(n => drawSet.has(n)).length;

        hitDist[hits] = (hitDist[hits] || 0) + 1;
        totalHits += hits;
        if (hits > bestHit) bestHit = hits;

        const prize = prizeWeights[hits] || 0;
        drawPrize += prize;

        if (hits >= btConfig.minPrizeHits) {
          wins++;
          currentStreak++;
          if (currentStreak > bestWinStreak) bestWinStreak = currentStreak;
          currentLossStreak = 0;
        } else {
          currentLossStreak++;
          if (currentLossStreak > worstLossStreak) worstLossStreak = currentLossStreak;
          currentStreak = 0;
        }
      }

      const netDraw = drawPrize - drawCost;
      balance += netDraw;
      equityCurve.push({ x: drawIdx + 1, y: Math.round(balance * 100) / 100 });
      dailyReturns.push(netDraw);

      if (balance > peak) peak = balance;
      const drawdown = peak > 0 ? (peak - balance) : Math.abs(balance);
      if (drawdown > maxDrawdown) maxDrawdown = drawdown;
    });

    const avgHits = totalHits / totalTests;
    const winRate = (wins / totalTests) * 100;

    // Consistency: inverse coefficient of variation
    const hitValues = Object.entries(hitDist).flatMap(([h, c]) => Array(c).fill(Number(h)));
    const variance = hitValues.length > 0 ? hitValues.reduce((s, v) => s + (v - avgHits) ** 2, 0) / hitValues.length : 0;
    const consistency = avgHits > 0 ? Math.max(0, 1 - Math.sqrt(variance) / avgHits) : 0;

    const profit = totalTests > 0 ? balance / (totalTests * costPerGame) : 0;

    // Recovery Factor = Net Profit / Max Drawdown
    const recoveryFactor = maxDrawdown > 0 ? balance / maxDrawdown : balance > 0 ? 10 : 0;

    // Simplified Sharpe Ratio
    const avgReturn = dailyReturns.reduce((a, b) => a + b, 0) / dailyReturns.length;
    const stdDevReturn = Math.sqrt(dailyReturns.reduce((s, v) => s + (v - avgReturn) ** 2, 0) / dailyReturns.length);
    const sharpeRatio = stdDevReturn > 0 ? (avgReturn / stdDevReturn) : 0;

    // Composite Score
    const globalScore = Math.round(
      (winRate * 2.5) + 
      (consistency * 30) + 
      (sharpeRatio * 15) + 
      (Math.min(10, recoveryFactor) * 2) +
      (avgHits * 10)
    );

    results.push({
      strategy,
      label: stratInfo?.label || strategy,
      totalTests,
      hitDistribution: hitDist,
      avgHits: Math.round(avgHits * 1000) / 1000,
      bestHit,
      winRate: Math.round(winRate * 100) / 100,
      profit: Math.round(profit * 100) / 100,
      consistency: Math.round(consistency * 1000) / 1000,
      streaks: { bestWin: bestWinStreak, worstLoss: worstLossStreak },
      equityCurve,
      maxDrawdown: Math.round(maxDrawdown * 100) / 100,
      recoveryFactor: Math.round(recoveryFactor * 100) / 100,
      sharpeRatio: Math.round(sharpeRatio * 100) / 100,
      globalScore,
    });
  }

  return results.sort((a, b) => b.globalScore - a.globalScore);
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";

export function useAdminCheck() {
  const { user } = useAuth();
  const [isAdmin, setIsAdmin] = useState(false);
  const [isSuperAdmin, setIsSuperAdmin] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) {
      setIsAdmin(false);
      setIsSuperAdmin(false);
      setLoading(false);
      return;
    }

    const check = async () => {
      const { data } = await supabase
        .from("user_roles")
        .select("role")
        .eq("user_id", user.id)
        .in("role", ["admin", "super_admin"]);
      const roles = (data || []).map((r: any) => r.role as string);
      setIsAdmin(roles.includes("admin") || roles.includes("super_admin"));
      setIsSuperAdmin(roles.includes("super_admin"));
      setLoading(false);
    };

    check();
  }, [user]);

  return { isAdmin, isSuperAdmin, loading };
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export interface GenerationRecord {
  id: string;
  lottery_id: string;
  numbers: number[];
  score: number;
  strategy: string;
  description: string;
  pipeline: { step: string; detail: string; count: number }[];
  created_at: string;
}

export function useGenerationHistory(lotteryId: string) {
  const [history, setHistory] = useState<GenerationRecord[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchHistory = useCallback(async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    const { data, error } = await supabase
      .from("generation_history")
      .select("*")
      .eq("user_id", user.id)
      .eq("lottery_id", lotteryId)
      .order("created_at", { ascending: false })
      .limit(10);

    if (!error && data) {
      setHistory(data as any[]);
    }
    setLoading(false);
  }, [lotteryId]);

  useEffect(() => {
    fetchHistory();
  }, [fetchHistory]);

  const saveGeneration = useCallback(async (record: {
    numbers: number[];
    score: number;
    strategy: string;
    description: string;
    pipeline: any;
  }) => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;

    const { data, error } = await supabase
      .from("generation_history")
      .insert({
        user_id: user.id,
        lottery_id: lotteryId,
        numbers: record.numbers,
        score: record.score,
        strategy: record.strategy,
        description: record.description,
        pipeline: record.pipeline,
      })
      .select()
      .single();

    if (error) {
      console.error("Error saving generation:", error);
      return null;
    }

    setHistory(prev => [data as any, ...prev].slice(0, 10));
    return data;
  }, [lotteryId]);

  const deleteGeneration = useCallback(async (id: string) => {
    const { error } = await supabase.from("generation_history").delete().eq("id", id);
    if (error) {
      toast.error("Erro ao remover registro");
      return;
    }
    setHistory(prev => prev.filter(item => item.id !== id));
  }, []);

  return { 
    history, 
    loading, 
    saveGeneration, 
    deleteGeneration, 
    refetch: fetchHistory 
  };
}

import { supabase } from "@/integrations/supabase/client";
import { DrawResult } from "@/data/lotteries";
import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";

export interface PrizeTierInfo {
  descricao: string;
  faixa: number;
  ganhadores: number;
  valorPremio: number;
}

export interface DrawPrizeData {
  premiacoes: PrizeTierInfo[];
  acumulou: boolean;
  valorAcumulado: number;
  valorEstimado: number;
  valorArrecadado: number;
}

export interface DrawResultWithPrizes extends DrawResult {
  prizeTiers?: DrawPrizeData | null;
}

/**
 * Hook to load lottery draws from Supabase database
 */
export function useLotteryDraws(lotteryId: string) {
  const [draws, setDraws] = useState<DrawResult[]>([]);
  const [drawsWithPrizes, setDrawsWithPrizes] = useState<DrawResultWithPrizes[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [count, setCount] = useState(0);

  const fetchDraws = useCallback(async () => {
    setLoading(true);
    try {
      let allData: any[] = [];
      let from = 0;
      const pageSize = 1000;
      let totalCount = 0;

      while (true) {
        const { data, error: pageError, count } = await supabase
          .from("lottery_draws")
          .select("concurso, draw_date, numbers, prize_tiers", { count: "exact" })
          .eq("lottery_id", lotteryId)
          .order("concurso", { ascending: false })
          .range(from, from + pageSize - 1);

        if (pageError) throw pageError;
        if (count !== null) totalCount = count;
        if (!data || data.length === 0) break;
        allData = allData.concat(data);
        if (data.length < pageSize) break;
        from += pageSize;
      }

      const mapped: DrawResult[] = allData.map((row: any) => ({
        concurso: row.concurso,
        date: row.draw_date || "",
        numbers: row.numbers || [],
      }));

      const mappedWithPrizes: DrawResultWithPrizes[] = allData.map((row: any) => ({
        concurso: row.concurso,
        date: row.draw_date || "",
        numbers: row.numbers || [],
        prizeTiers: row.prize_tiers as DrawPrizeData | null,
      }));

      setDraws(mapped);
      setDrawsWithPrizes(mappedWithPrizes);
      setCount(totalCount || mapped.length);
    } catch (e) {
      console.error("Error fetching draws:", e);
    } finally {
      setLoading(false);
    }
  }, [lotteryId]);

  const syncDraws = useCallback(async () => {
    setSyncing(true);
    try {
      const { data, error } = await supabase.functions.invoke("sync-lottery-draws", {
        body: { lottery_id: lotteryId },
      });

      if (error) throw error;

      const result = data?.results?.[0];
      if (result) {
        if (result.inserted > 0) {
          toast.success(`${result.inserted} novos concursos importados para ${lotteryId}`);
        } else {
          toast.info("Banco de dados já está atualizado");
        }
        if (result.errors > 0) {
          toast.warning(`${result.errors} erros durante a importação`);
        }
      }

      await fetchDraws();
    } catch (e) {
      console.error("Sync error:", e);
      toast.error("Erro ao sincronizar: " + (e instanceof Error ? e.message : "Erro desconhecido"));
    } finally {
      setSyncing(false);
    }
  }, [lotteryId, fetchDraws]);

  const syncAllLotteries = useCallback(async () => {
    setSyncing(true);
    try {
      const { data, error } = await supabase.functions.invoke("sync-lottery-draws", {
        body: {},
      });

      if (error) throw error;

      let totalInserted = 0;
      let totalErrors = 0;
      (data?.results || []).forEach((r: any) => {
        totalInserted += r.inserted || 0;
        totalErrors += r.errors || 0;
      });

      if (totalInserted > 0) {
        toast.success(`${totalInserted} concursos importados de todas as loterias`);
      } else {
        toast.info("Todas as loterias já estão atualizadas");
      }
      if (totalErrors > 0) {
        toast.warning(`${totalErrors} erros durante a importação`);
      }

      await fetchDraws();
    } catch (e) {
      console.error("Sync all error:", e);
      toast.error("Erro ao sincronizar todas as loterias");
    } finally {
      setSyncing(false);
    }
  }, [fetchDraws]);

  const addDraw = useCallback((draw: DrawResult) => {
    setDraws(prev => {
      if (prev.some(d => d.concurso === draw.concurso)) return prev;
      return [draw, ...prev].sort((a, b) => b.concurso - a.concurso);
    });
  }, []);

  useEffect(() => {
    fetchDraws();
  }, [fetchDraws]);

  return {
    draws,
    drawsWithPrizes,
    loading,
    syncing,
    count,
    syncDraws,
    syncAllLotteries,
    addDraw,
    refetch: fetchDraws,
  };
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { usePlanAccess, PLAN_LIMITS } from "@/hooks/usePlanAccess";

export interface SavedBet {
  id: string;
  lottery_id: string;
  numbers: number[];
  strategy: string | null;
  score: number | null;
  grade: string | null;
  label: string | null;
  created_at: string;
}

export function useSavedBets(lotteryId: string) {
  const [savedBets, setSavedBets] = useState<SavedBet[]>([]);
  const [loading, setLoading] = useState(true);
  const { currentPlan } = usePlanAccess();
  const limit = PLAN_LIMITS[currentPlan].savedBetsPerLottery;

  const fetchBets = useCallback(async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    const { data, error } = await supabase
      .from("saved_bets")
      .select("*")
      .eq("user_id", user.id)
      .eq("lottery_id", lotteryId)
      .order("created_at", { ascending: false });

    if (!error && data) {
      setSavedBets(data as SavedBet[]);
    }
    setLoading(false);
  }, [lotteryId]);

  useEffect(() => {
    fetchBets();
  }, [fetchBets]);

  const saveBet = useCallback(async (bet: {
    numbers: number[];
    strategy?: string;
    score?: number;
    grade?: string;
    label?: string;
  }) => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      toast.error("Faça login para salvar apostas");
      return false;
    }

    if (savedBets.length >= limit) {
      toast.error(`Limite de ${limit} jogos salvos por loteria no plano gratuito. Faça upgrade para salvar mais!`);
      return false;
    }

    const { error } = await supabase.from("saved_bets").insert({
      user_id: user.id,
      lottery_id: lotteryId,
      numbers: bet.numbers,
      strategy: bet.strategy || null,
      score: bet.score || null,
      grade: bet.grade || null,
      label: bet.label || null,
    });

    if (error) {
      toast.error("Erro ao salvar aposta");
      return false;
    }

    toast.success("Aposta salva!");
    fetchBets();
    return true;
  }, [lotteryId, fetchBets]);

  const updateBet = useCallback(async (id: string, updates: { label?: string; strategy?: string }) => {
    const { error } = await supabase.from("saved_bets").update(updates).eq("id", id);
    if (error) {
      toast.error("Erro ao atualizar aposta");
      return false;
    }
    toast.success("Aposta atualizada");
    setSavedBets(prev => prev.map(b => b.id === id ? { ...b, ...updates } : b));
    return true;
  }, []);

  const deleteBet = useCallback(async (id: string) => {
    const { error } = await supabase.from("saved_bets").delete().eq("id", id);
    if (error) {
      toast.error("Erro ao remover aposta");
      return;
    }
    toast.success("Aposta removida");
    setSavedBets(prev => prev.filter(b => b.id !== id));
  }, []);

  const remaining = Math.max(0, limit - savedBets.length);
  const isAtLimit = remaining === 0 && limit !== Infinity;

  return { savedBets, loading, saveBet, updateBet, deleteBet, refetch: fetchBets, limit, remaining, isAtLimit };
}

// Synthesized alert sounds using Web Audio API — no external dependencies
// Different melodies per match tier: low matches → simple beep, high matches → celebratory fanfare

import { getSoundSettings } from "@/hooks/useSoundSettings";

type Tier = "low" | "mid" | "high" | "jackpot";

function getTier(matchCount: number, pick: number): Tier {
  const ratio = matchCount / pick;
  if (ratio >= 1) return "jackpot";
  if (ratio >= 0.7) return "high";
  if (ratio >= 0.5) return "mid";
  return "low";
}

function playTone(ctx: AudioContext, freq: number, start: number, duration: number, gain = 0.25, type: OscillatorType = "sine") {
  const osc = ctx.createOscillator();
  const g = ctx.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  g.gain.setValueAtTime(gain, start);
  g.gain.exponentialRampToValueAtTime(0.001, start + duration);
  osc.connect(g).connect(ctx.destination);
  osc.start(start);
  osc.stop(start + duration);
}

const MELODIES: Record<Tier, { notes: [number, number][]; type: OscillatorType }> = {
  low: {
    notes: [[523, 0.15], [659, 0.2]],
    type: "sine",
  },
  mid: {
    notes: [[523, 0.15], [659, 0.15], [784, 0.25]],
    type: "triangle",
  },
  high: {
    notes: [[523, 0.12], [659, 0.12], [784, 0.12], [1047, 0.3]],
    type: "triangle",
  },
  jackpot: {
    notes: [
      [523, 0.1], [659, 0.1], [784, 0.1],
      [1047, 0.15], [1047, 0.1], [1175, 0.1], [1319, 0.4],
    ],
    type: "square",
  },
};

let audioCtx: AudioContext | null = null;

function getAudioContext(): AudioContext | null {
  try {
    if (!audioCtx || audioCtx.state === "closed") {
      audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtx.state === "suspended") {
      audioCtx.resume();
    }
    return audioCtx;
  } catch {
    return null;
  }
}

export function playMatchAlert(matchCount: number, pick: number) {
  const { muted, volume } = getSoundSettings();
  if (muted || volume === 0) return;

  const ctx = getAudioContext();
  if (!ctx) return;

  const volumeMultiplier = volume / 100;
  const tier = getTier(matchCount, pick);
  const melody = MELODIES[tier];
  const baseGain = (tier === "jackpot" ? 0.3 : tier === "high" ? 0.25 : 0.2) * volumeMultiplier;

  let t = ctx.currentTime + 0.05;
  for (const [freq, dur] of melody.notes) {
    playTone(ctx, freq, t, dur, baseGain, melody.type);
    t += dur * 0.85;
  }
}

export function playSimpleBeep() {
  const { muted, volume } = getSoundSettings();
  if (muted || volume === 0) return;

  const ctx = getAudioContext();
  if (!ctx) return;
  playTone(ctx, 880, ctx.currentTime, 0.12, 0.15 * (volume / 100), "sine");
}

/** Play a preview of a specific tier — used in settings */
export function playTierPreview(tier: Tier) {
  const { volume } = getSoundSettings();
  const ctx = getAudioContext();
  if (!ctx) return;

  const volumeMultiplier = volume / 100;
  const melody = MELODIES[tier];
  const baseGain = 0.25 * volumeMultiplier;

  let t = ctx.currentTime + 0.05;
  for (const [freq, dur] of melody.notes) {
    playTone(ctx, freq, t, dur, baseGain, melody.type);
    t += dur * 0.85;
  }
}

