            <motion.div variants={item} className="lg:col-span-1">
              <StatsCard 
                title="Volatilidade" 
                value={`${volatilityIndex.toFixed(1)}%`} 
                icon={TrendingUp} 
                color={volatilityIndex > 20 ? "amber" : "blue"} 
