                                                      </div>
                                                    </TableCell>
                                                    <TableCell className="text-[9px] py-1 px-2">
                                                      {r.isPrize ? (
                                                        <span className="text-primary font-semibold">{r.tierLabel}</span>
                                                      ) : "—"}
                                                    </TableCell>
                                                  </TableRow>
                                                ))}
                                              </TableBody>
                                            </Table>
                                          </div>
                                        </div>
                                      </motion.div>
                                    )}
                                  </AnimatePresence>
                                </div>
                              </motion.div>
                            );
                          })}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </Card>
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
};

