// ═══════════════════════════════════════════════════════
// Web Worker: Motor de Simulação Massiva v2.0
// Runs bitset simulation off the main thread
// ═══════════════════════════════════════════════════════

// ─── Inline PRNG (can't import from main thread modules) ───
let _seed = Date.now() | 0;

function seedRNG(s: number): void {
  _seed = s | 0;
}

function fastRandom(): number {
  _seed = (_seed * 1664525 + 1013904223) | 0;
  return (_seed >>> 0) / 4294967296;
}

function fastRandInt(max: number): number {
  _seed = (_seed * 1664525 + 1013904223) | 0;
  return ((_seed >>> 0) % max);
}

function fastGenerateDraw(maxNumber: number, pick: number, pool: Uint8Array): Uint8Array {
  for (let i = 0; i < maxNumber; i++) pool[i] = i + 1;
  for (let i = 0; i < pick; i++) {
    const j = i + fastRandInt(maxNumber - i);
    const tmp = pool[i]; pool[i] = pool[j]; pool[j] = tmp;
  }
  const result = new Uint8Array(pick);
  for (let i = 0; i < pick; i++) result[i] = pool[i];
  result.sort();
  return result;
}

function fastWeightedDraw(weights: Float32Array, pick: number): Uint8Array {
  const n = weights.length;
  const selected = new Uint8Array(pick);
  const used = new Uint8Array(n);
  const cumulative = new Float32Array(n);
  let count = 0;

  while (count < pick) {
    let total = 0;
    for (let i = 0; i < n; i++) {
      if (used[i]) { cumulative[i] = total; } else { total += weights[i]; cumulative[i] = total; }
    }
    if (total <= 0) {
      for (let i = 0; i < n && count < pick; i++) {
        if (!used[i]) { selected[count++] = i + 1; used[i] = 1; }
      }
      break;
    }
    const r = fastRandom() * total;
    for (let i = 0; i < n; i++) {
      if (!used[i] && cumulative[i] >= r) { selected[count++] = i + 1; used[i] = 1; break; }
    }
  }
  selected.sort();
  return selected;
}

// ─── Bitset ops ───
function toBitset(numbers: number[]): Uint32Array {
  const bs = new Uint32Array(4);
  for (const n of numbers) { bs[(n - 1) >> 5] |= (1 << ((n - 1) & 31)); }
  return bs;
}

function bitsetIntersectionCount(a: Uint32Array, b: Uint32Array): number {
  let count = 0;
  for (let i = 0; i < 4; i++) {
    let v = a[i] & b[i];
    v = v - ((v >> 1) & 0x55555555);
    v = (v & 0x33333333) + ((v >> 2) & 0x33333333);
    count += (((v + (v >> 4)) & 0x0F0F0F0F) * 0x01010101) >> 24;
  }
  return count;
}

// ─── Pattern analysis ───
function analyzePattern(numbers: number[], maxNumber: number) {
  let evenCount = 0, sum = 0, consecutivePairs = 0, clusters = 1;
  for (let i = 0; i < numbers.length; i++) {
    const n = numbers[i]; sum += n;
    if (n % 2 === 0) evenCount++;
    if (i > 0) {
      if (numbers[i] - numbers[i - 1] === 1) consecutivePairs++;
      else if (numbers[i] - numbers[i - 1] > 3) clusters++;
    }
  }
  return { evenCount, oddCount: numbers.length - evenCount, sum, consecutivePairs, rangeSpread: numbers[numbers.length - 1] - numbers[0], clusters };
}

function getPrizeThreshold(lotteryId: string, pick: number): number {
  const t: Record<string, number> = { megasena: 4, lotofacil: 11, quina: 2, lotomania: 15, duplasena: 3, timemania: 3, diadesorte: 4, supersete: 3 };
  return t[lotteryId] ?? Math.max(2, pick - 3);
}

// ─── Weight building ───
interface StatInput { percentage: number; recentFreq: number; cycleScore: number; trend: number; momentum: number; lastSeen: number; }

function buildWeights(stats: StatInput[], numCount: number, mode: string): Float32Array {
  const w = new Float32Array(numCount);
  if (mode === "random") { for (let i = 0; i < numCount; i++) w[i] = 1; return w; }
  for (let i = 0; i < numCount; i++) {
    const s = stats[i];
    if (!s) { w[i] = 1; continue; }
    if (mode === "statistical") {
      w[i] = s.percentage * 0.3 + s.recentFreq * 0.4 + s.cycleScore * 0.3;
    } else if (mode === "ai_weighted") {
      const tb = s.trend > 0 ? 1 + s.trend * 0.5 : 1;
      const mb = s.momentum > 0 ? 1 + s.momentum * 0.3 : 1;
      const cb = s.cycleScore > 0.5 ? 1 + (s.cycleScore - 0.5) : 1;
      const rb = s.lastSeen < 5 ? 1.2 : s.lastSeen > 15 ? 0.8 : 1;
      w[i] = s.percentage * tb * mb * cb * rb;
    } else {
      const base = s.percentage * 0.25 + s.recentFreq * 0.25;
      const trend = s.trend > 0 ? 1 + s.trend * 0.3 : 1;
      const cycle = 1 + s.cycleScore * 0.2;
      w[i] = base * trend * cycle;
    }
    w[i] = Math.max(0.01, w[i]);
  }
  return w;
}

// ─── Insights ───
function generatePatternInsights(games: any[], config: any) {
  if (games.length === 0) return [];
  const insights: any[] = [];
  const n = games.length;

  const avgEven = games.reduce((s: number, g: any) => s + g.evenCount, 0) / n;
  const evenRatio = avgEven / config.pick;
  insights.push({ label: "Equilíbrio Par/Ímpar", description: `Jogos top têm em média ${avgEven.toFixed(1)} pares e ${(config.pick - avgEven).toFixed(1)} ímpares`, value: `${(evenRatio * 100).toFixed(0)}% / ${((1 - evenRatio) * 100).toFixed(0)}%`, trend: Math.abs(evenRatio - 0.5) < 0.1 ? "positive" : "neutral" });

  const avgSum = games.reduce((s: number, g: any) => s + g.sum, 0) / n;
  const minSum = Math.min(...games.map((g: any) => g.sum));
  const maxSum = Math.max(...games.map((g: any) => g.sum));
  insights.push({ label: "Soma das Dezenas", description: `Faixa ideal: ${minSum} a ${maxSum}`, value: `Média: ${avgSum.toFixed(0)}`, trend: "neutral" });

  const avgConsec = games.reduce((s: number, g: any) => s + g.consecutivePairs, 0) / n;
  insights.push({ label: "Pares Consecutivos", description: `Jogos eficientes têm ~${avgConsec.toFixed(1)} pares consecutivos`, value: avgConsec.toFixed(1), trend: avgConsec > 0.5 && avgConsec < 3 ? "positive" : "neutral" });

  const avgSpread = games.reduce((s: number, g: any) => s + g.rangeSpread, 0) / n;
  insights.push({ label: "Cobertura de Faixa", description: `Amplitude média dos jogos top`, value: `${avgSpread.toFixed(0)} de ${config.numbers}`, trend: avgSpread / config.numbers > 0.6 ? "positive" : "negative" });

  const numFreq = new Map<number, number>();
  for (const g of games) { for (const num of g.numbers) { numFreq.set(num, (numFreq.get(num) || 0) + 1); } }
  const topNums = [...numFreq.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5);
  insights.push({ label: "Dezenas Mais Frequentes nos Top", description: `Números que aparecem mais nos jogos de melhor desempenho`, value: topNums.map(([n]) => n.toString().padStart(2, "0")).join(", "), trend: "positive" });
  const bottomNums = [...numFreq.entries()].sort((a, b) => a[1] - b[1]).slice(0, 5);
  insights.push({ label: "Dezenas Raras nos Top Games", description: `Números que pouco aparecem nos jogos de melhor desempenho`, value: bottomNums.map(([n]) => n.toString().padStart(2, "0")).join(", "), trend: "negative" });

  return insights;
}

function computeDistributionSummary(games: any[], drawCount: number) {
  if (games.length === 0) return { avgSum: 0, avgEvenRatio: 0, avgConsecutive: 0, avgSpread: 0, bestHitOverall: 0, avgPrizeRate: 0 };
  const n = games.length;
  return {
    avgSum: Math.round(games.reduce((s: number, g: any) => s + g.sum, 0) / n),
    avgEvenRatio: Math.round((games.reduce((s: number, g: any) => s + g.evenCount / (g.evenCount + g.oddCount), 0) / n) * 100) / 100,
    avgConsecutive: Math.round((games.reduce((s: number, g: any) => s + g.consecutivePairs, 0) / n) * 10) / 10,
    avgSpread: Math.round(games.reduce((s: number, g: any) => s + g.rangeSpread, 0) / n),
    bestHitOverall: Math.max(...games.map((g: any) => g.bestHit)),
    avgPrizeRate: Math.round((games.reduce((s: number, g: any) => s + g.prizeCount / drawCount, 0) / n) * 10000) / 100,
  };
}

// ─── Main simulation ───
function runBatch(job: any) {
  const { config, draws, stats, totalGames, mode, topN } = job;
  if (draws.length === 0) return { topGames: [], totalGenerated: 0, totalEvaluated: 0, elapsedMs: 0, opsPerSecond: 0, patternInsights: [], distributionSummary: { avgSum: 0, avgEvenRatio: 0, avgConsecutive: 0, avgSpread: 0, bestHitOverall: 0, avgPrizeRate: 0 } };

  const drawBitsets = draws.map((d: any) => toBitset(d.numbers));
  const drawCount = draws.length;
  const prizeThreshold = getPrizeThreshold(config.id, config.pick);
  const weights = buildWeights(stats, config.numbers, mode);
  const pool = new Uint8Array(config.numbers);
  seedRNG(Date.now() | 0);

  const topGames: any[] = [];
  let minTopScore = -Infinity;
  let totalEvaluated = 0;
  const start = performance.now();

  for (let g = 0; g < totalGames; g++) {
    let gameNumbers: number[];
    if (mode === "random") {
      gameNumbers = Array.from(fastGenerateDraw(config.numbers, config.pick, pool));
    } else {
      gameNumbers = Array.from(fastWeightedDraw(weights, config.pick));
    }

    const gameBitset = toBitset(gameNumbers);
    const hitDist: Record<number, number> = {};
    for (let h = 0; h <= config.pick; h++) hitDist[h] = 0;

    let totalHits = 0, bestHit = 0, prizeCount = 0, hitSquaredSum = 0;
    for (let d = 0; d < drawCount; d++) {
      const hits = bitsetIntersectionCount(gameBitset, drawBitsets[d]);
      hitDist[hits] = (hitDist[hits] || 0) + 1;
      totalHits += hits; hitSquaredSum += hits * hits;
      if (hits > bestHit) bestHit = hits;
      if (hits >= prizeThreshold) prizeCount++;
    }
    totalEvaluated += drawCount;

    const avgHits = totalHits / drawCount;
    const variance = (hitSquaredSum / drawCount) - (avgHits * avgHits);
    const stability = Math.sqrt(Math.max(0, variance));
    const pattern = analyzePattern(gameNumbers, config.numbers);
    const score = avgHits * 30 + bestHit * 20 + (prizeCount / drawCount) * 100 * 25 + (1 / (1 + stability)) * 15 + (pattern.rangeSpread / config.numbers) * 10;

    if (topGames.length < topN || score > minTopScore) {
      const game = { numbers: gameNumbers, totalHits, avgHits: Math.round(avgHits * 1000) / 1000, bestHit, prizeCount, hitDistribution: hitDist, stability: Math.round(stability * 1000) / 1000, score: Math.round(score * 100) / 100, ...pattern };
      if (topGames.length < topN) {
        topGames.push(game);
        if (topGames.length === topN) { topGames.sort((a, b) => b.score - a.score); minTopScore = topGames[topGames.length - 1].score; }
      } else {
        topGames[topGames.length - 1] = game;
        topGames.sort((a, b) => b.score - a.score);
        minTopScore = topGames[topGames.length - 1].score;
      }
    }
  }

  topGames.sort((a, b) => b.score - a.score);
  const elapsedMs = Math.round(performance.now() - start);
  return { topGames, totalGenerated: totalGames, totalEvaluated, elapsedMs, opsPerSecond: Math.round(totalEvaluated / (elapsedMs / 1000)), patternInsights: generatePatternInsights(topGames, config), distributionSummary: computeDistributionSummary(topGames, drawCount) };
}

// ─── Worker message handler ───
self.onmessage = (e: MessageEvent) => {
  const { type, job } = e.data;

  if (type === "run_massive_sim") {
    const { totalGames, batchSize } = job;
    const chunks = Math.ceil(totalGames / batchSize);
    const allTopGames: any[] = [];
    let totalEval = 0;
    const startTime = performance.now();

    for (let c = 0; c < chunks; c++) {
      const chunkGames = Math.min(batchSize, totalGames - c * batchSize);
      const result = runBatch({ ...job, totalGames: chunkGames });
      allTopGames.push(...result.topGames);
      totalEval += result.totalEvaluated;

      // Send progress
      self.postMessage({
        type: "progress",
        data: {
          gamesGenerated: Math.min((c + 1) * batchSize, totalGames),
          gamesEvaluated: totalEval,
          totalGames,
          elapsedMs: Math.round(performance.now() - startTime),
          opsPerSecond: result.opsPerSecond,
          phase: c === chunks - 1 ? "filtering" : "evaluating",
        },
      });
    }

    // Merge and finalize
    const topN = job.topN || 50;
    const finalTopGames = allTopGames.sort((a, b) => b.score - a.score).slice(0, topN);
    const totalElapsed = Math.round(performance.now() - startTime);
    const patternInsights = generatePatternInsights(finalTopGames, job.config);
    const distributionSummary = computeDistributionSummary(finalTopGames, job.draws.length);

    self.postMessage({
      type: "result",
      data: {
        topGames: finalTopGames,
        totalGenerated: totalGames,
        totalEvaluated: totalEval,
        elapsedMs: totalElapsed,
        opsPerSecond: Math.round(totalEval / (totalElapsed / 1000)),
        patternInsights,
        distributionSummary,
      },
    });
  }
};

// ═══════════════════════════════════════════════════════
// Web Worker: Simulador Monte Carlo por Estratégias
// Runs strategy-based Monte Carlo off the main thread
// ═══════════════════════════════════════════════════════

// ─── Inline strategy generation (no module imports in workers) ───

interface StatInput {
  number: number; frequency: number; percentage: number; lastSeen: number;
  trend: number; status: string; recentFreq: number; stdDevIntervals: number;
  momentum: number; cycleScore: number;
}

interface ConfigInput { id: string; name: string; numbers: number; pick: number; color: string; icon: string; }
interface DrawInput { concurso: number; date: string; numbers: number[]; }

function generateSmartDraw(stats: StatInput[], config: ConfigInput): number[] {
  const sorted = [...stats].sort((a, b) => {
    const scoreA = a.percentage * 0.3 + a.recentFreq * 0.3 + a.trend * 0.2 + a.cycleScore * 0.2;
    const scoreB = b.percentage * 0.3 + b.recentFreq * 0.3 + b.trend * 0.2 + b.cycleScore * 0.2;
    return scoreB - scoreA;
  });
  const pool = sorted.slice(0, Math.min(config.numbers, Math.ceil(config.pick * 2.5)));
  const selected: number[] = [];
  while (selected.length < config.pick && pool.length > 0) {
    const idx = Math.floor(Math.random() * pool.length);
    selected.push(pool[idx].number);
    pool.splice(idx, 1);
  }
  return selected.sort((a, b) => a - b);
}

function generateHotDraw(stats: StatInput[], config: ConfigInput): number[] {
  const hot = [...stats].filter(s => s.status === "hot").sort((a, b) => b.frequency - a.frequency);
  const pool = hot.length >= config.pick ? hot : [...stats].sort((a, b) => b.frequency - a.frequency);
  const selected: number[] = [];
  const candidates = pool.slice(0, Math.ceil(config.pick * 2));
  while (selected.length < config.pick && candidates.length > 0) {
    const idx = Math.floor(Math.random() * candidates.length);
    selected.push(candidates[idx].number);
    candidates.splice(idx, 1);
  }
  return selected.sort((a, b) => a - b);
}

function generateColdDraw(stats: StatInput[], config: ConfigInput): number[] {
  const cold = [...stats].filter(s => s.status === "cold").sort((a, b) => a.frequency - b.frequency);
  const pool = cold.length >= config.pick ? cold : [...stats].sort((a, b) => a.frequency - b.frequency);
  const candidates = pool.slice(0, Math.ceil(config.pick * 2));
  const selected: number[] = [];
  while (selected.length < config.pick && candidates.length > 0) {
    const idx = Math.floor(Math.random() * candidates.length);
    selected.push(candidates[idx].number);
    candidates.splice(idx, 1);
  }
  return selected.sort((a, b) => a - b);
}

function generateBalancedDraw(stats: StatInput[], config: ConfigInput): number[] {
  const hot = stats.filter(s => s.status === "hot");
  const cold = stats.filter(s => s.status === "cold");
  const neutral = stats.filter(s => s.status === "neutral");
  const hotPick = Math.ceil(config.pick * 0.4);
  const coldPick = Math.ceil(config.pick * 0.3);
  const neutralPick = config.pick - hotPick - coldPick;
  const pick = (arr: StatInput[], n: number) => {
    const shuffled = [...arr].sort(() => Math.random() - 0.5);
    return shuffled.slice(0, n).map(s => s.number);
  };
  const result = [...pick(hot, hotPick), ...pick(cold, coldPick), ...pick(neutral, neutralPick)];
  while (result.length < config.pick) {
    const n = Math.floor(Math.random() * config.numbers) + 1;
    if (!result.includes(n)) result.push(n);
  }
  return result.slice(0, config.pick).sort((a, b) => a - b);
}

function generateRandomDraw(config: ConfigInput): number[] {
  const nums: number[] = [];
  while (nums.length < config.pick) {
    const n = Math.floor(Math.random() * config.numbers) + 1;
    if (!nums.includes(n)) nums.push(n);
  }
  return nums.sort((a, b) => a - b);
}

function generateTrendDraw(stats: StatInput[], config: ConfigInput): number[] {
  const sorted = [...stats].sort((a, b) => b.trend - a.trend);
  const pool = sorted.slice(0, Math.ceil(config.pick * 2));
  const selected: number[] = [];
  while (selected.length < config.pick && pool.length > 0) {
    const idx = Math.floor(Math.random() * pool.length);
    selected.push(pool[idx].number);
    pool.splice(idx, 1);
  }
  return selected.sort((a, b) => a - b);
}

function generateCycleDraw(stats: StatInput[], config: ConfigInput): number[] {
  const sorted = [...stats].sort((a, b) => b.cycleScore - a.cycleScore);
  const pool = sorted.slice(0, Math.ceil(config.pick * 2));
  const selected: number[] = [];
  while (selected.length < config.pick && pool.length > 0) {
    const idx = Math.floor(Math.random() * pool.length);
    selected.push(pool[idx].number);
    pool.splice(idx, 1);
  }
  return selected.sort((a, b) => a - b);
}

function generateHybridDraw(stats: StatInput[], config: ConfigInput): number[] {
  const sorted = [...stats].sort((a, b) => {
    const sa = a.percentage * 0.2 + a.recentFreq * 0.2 + a.trend * 0.2 + a.cycleScore * 0.2 + a.momentum * 0.2;
    const sb = b.percentage * 0.2 + b.recentFreq * 0.2 + b.trend * 0.2 + b.cycleScore * 0.2 + b.momentum * 0.2;
    return sb - sa;
  });
  const pool = sorted.slice(0, Math.ceil(config.pick * 2.5));
  const selected: number[] = [];
  while (selected.length < config.pick && pool.length > 0) {
    const idx = Math.floor(Math.random() * pool.length);
    selected.push(pool[idx].number);
    pool.splice(idx, 1);
  }
  return selected.sort((a, b) => a - b);
}

function generateByStrategy(strategy: string, stats: StatInput[], config: ConfigInput): number[] {
  switch (strategy) {
    case "smart": return generateSmartDraw(stats, config);
    case "hot": return generateHotDraw(stats, config);
    case "cold": return generateColdDraw(stats, config);
    case "balanced": return generateBalancedDraw(stats, config);
    case "trend": return generateTrendDraw(stats, config);
    case "cycle": return generateCycleDraw(stats, config);
    case "hybrid": return generateHybridDraw(stats, config);
    default: return generateSmartDraw(stats, config);
  }
}

// ─── Simulation logic ───

function countHits(bet: number[], draw: number[]): number {
  let hits = 0;
  const drawSet = new Set(draw);
  for (const n of bet) { if (drawSet.has(n)) hits++; }
  return hits;
}

function getPrizeMultipliers(lotteryId: string, pick: number): Record<number, number> {
  const base: Record<number, number> = {};
  for (let i = 0; i <= pick; i++) base[i] = 0;
  switch (lotteryId) {
    case "megasena": base[4] = 50; base[5] = 5000; base[6] = 500000; break;
    case "lotofacil": base[11] = 5; base[12] = 10; base[13] = 25; base[14] = 1500; base[15] = 100000; break;
    case "quina": base[2] = 1; base[3] = 5; base[4] = 200; base[5] = 50000; break;
    case "lotomania": base[0] = 5; base[15] = 10; base[16] = 25; base[17] = 100; base[18] = 1000; base[19] = 20000; base[20] = 500000; break;
    case "duplasena": base[3] = 3; base[4] = 50; base[5] = 5000; base[6] = 300000; break;
    case "timemania": base[3] = 2; base[4] = 10; base[5] = 50; base[6] = 500; base[7] = 50000; break;
    case "diadesorte": base[4] = 10; base[5] = 50; base[6] = 2000; base[7] = 200000; break;
    case "supersete": base[3] = 5; base[4] = 20; base[5] = 200; base[6] = 10000; base[7] = 500000; break;
    default: base[pick - 2] = 10; base[pick - 1] = 1000; base[pick] = 100000;
  }
  return base;
}

const STRATEGY_LABELS: Record<string, string> = {
  smart: "Inteligente", hot: "Quentes", cold: "Frias", balanced: "Equilibrada",
  trend: "Tendência", cycle: "Ciclo", hybrid: "Híbrida", ml: "IA Ensemble",
  fibonacci: "Fibonacci", primes: "Primos", golden: "Razão Áurea",
  pattern: "Padrão", lowDelay: "Baixo Atraso", sectors: "Setores",
};

self.onmessage = (e: MessageEvent) => {
  const { type, job } = e.data;

  if (type === "run_monte_carlo") {
    const { stats, config, draws, simConfig } = job;
    const start = performance.now();
    const prizeMultipliers = getPrizeMultipliers(config.id, config.pick);
    const performances: any[] = [];
    const convergenceData: any[] = [];

    const strategiesToRun = simConfig.compareWithRandom
      ? [...new Set([...simConfig.strategies, "smart"])]
      : [...new Set(simConfig.strategies)];

    for (let si = 0; si < strategiesToRun.length; si++) {
      const strategy = strategiesToRun[si];
      const iterPerStrategy = Math.floor(simConfig.iterations / strategiesToRun.length);
      const label = STRATEGY_LABELS[strategy] || strategy;

      const hitDist: Record<number, number> = {};
      for (let i = 0; i <= config.pick; i++) hitDist[i] = 0;
      let totalHits = 0, bestHit = 0;
      const convergence: number[] = [];
      const sampleInterval = Math.max(1, Math.floor(iterPerStrategy / 50));

      for (let i = 0; i < iterPerStrategy; i++) {
        const bet = generateByStrategy(strategy, stats, config);
        const draw = draws.length > 0 ? draws[Math.floor(Math.random() * draws.length)].numbers : generateRandomDraw(config);
        const hits = countHits(bet, draw);
        hitDist[hits] = (hitDist[hits] || 0) + 1;
        totalHits += hits;
        if (hits > bestHit) bestHit = hits;
        if ((i + 1) % sampleInterval === 0) convergence.push(totalHits / (i + 1));
      }

      convergence.forEach((avg, idx) => {
        convergenceData.push({ iteration: (idx + 1) * sampleInterval, avgHits: Math.round(avg * 1000) / 1000, strategy: label });
      });

      const avgHits = totalHits / iterPerStrategy;
      const hitRate4Plus = Object.entries(hitDist).filter(([h]) => Number(h) >= 4).reduce((s, [, c]) => s + c, 0) / iterPerStrategy;
      const hitRate5Plus = Object.entries(hitDist).filter(([h]) => Number(h) >= 5).reduce((s, [, c]) => s + c, 0) / iterPerStrategy;
      const hitRateFull = (hitDist[config.pick] || 0) / iterPerStrategy;

      let ev = 0;
      for (const [hits, count] of Object.entries(hitDist)) { ev += (prizeMultipliers[Number(hits)] || 0) * count; }
      ev /= iterPerStrategy;

      const hitValues = Object.entries(hitDist).flatMap(([h, c]) => Array(c).fill(Number(h)));
      const mean = avgHits;
      const variance = hitValues.reduce((s, v) => s + (v - mean) ** 2, 0) / hitValues.length;
      const consistency = mean > 0 ? Math.max(0, 1 - Math.sqrt(variance) / mean) : 0;

      performances.push({
        strategy, label, totalGames: iterPerStrategy, hitDistribution: hitDist,
        avgHits: Math.round(avgHits * 1000) / 1000, bestHit,
        hitRate4Plus: Math.round(hitRate4Plus * 10000) / 100,
        hitRate5Plus: Math.round(hitRate5Plus * 10000) / 100,
        hitRateFull: Math.round(hitRateFull * 1000000) / 10000,
        expectedValue: Math.round(ev * 100) / 100,
        consistency: Math.round(consistency * 1000) / 1000,
      });

      // Progress per strategy
      self.postMessage({ type: "progress", data: { completed: si + 1, total: strategiesToRun.length, strategy: label } });
    }

    performances.sort((a, b) => b.expectedValue - a.expectedValue);

    const gamesPerYear = 156;
    const yearlyProjection = performances.map((p: any) => ({
      strategy: p.label, gamesPerYear,
      expectedHits4Plus: Math.round(p.hitRate4Plus / 100 * gamesPerYear * 10) / 10,
      expectedHits5Plus: Math.round(p.hitRate5Plus / 100 * gamesPerYear * 10) / 10,
      expectedFullHits: Math.round(p.hitRateFull / 100 * gamesPerYear * 10000) / 10000,
      roi: Math.round(p.expectedValue * 100) / 100,
    }));

    self.postMessage({
      type: "result",
      data: {
        totalIterations: simConfig.iterations,
        elapsedMs: Math.round(performance.now() - start),
        performances, convergenceData, yearlyProjection,
      },
    });
  }
};

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

export async function getSupabaseAdmin() {
  const url = Deno.env.get("SUPABASE_URL")!;
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  return createClient(url, key);
}

async function hashPayload(payload: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(payload);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, "0")).join("").slice(0, 32);
}

export async function getCachedAnalysis(
  supabase: any,
  lotteryId: string,
  functionName: string,
  inputData: any,
  ttlHours = 6
): Promise<any | null> {
  const cacheKey = await hashPayload(JSON.stringify(inputData));

  const { data } = await supabase
    .from("ai_analysis_cache")
    .select("result, expires_at")
    .eq("lottery_id", lotteryId)
    .eq("function_name", functionName)
    .eq("cache_key", cacheKey)
    .gt("expires_at", new Date().toISOString())
    .maybeSingle();

  if (data) {
    console.log(`Cache HIT for ${functionName}/${lotteryId}`);
    return data.result;
  }
  console.log(`Cache MISS for ${functionName}/${lotteryId}`);
  return null;
}

export async function setCachedAnalysis(
  supabase: any,
  lotteryId: string,
  functionName: string,
  inputData: any,
  result: any,
  ttlHours = 6
): Promise<void> {
  const cacheKey = await hashPayload(JSON.stringify(inputData));
  const expiresAt = new Date(Date.now() + ttlHours * 60 * 60 * 1000).toISOString();

  await supabase
    .from("ai_analysis_cache")
    .upsert({
      lottery_id: lotteryId,
      function_name: functionName,
      cache_key: cacheKey,
      result,
      expires_at: expiresAt,
    }, { onConflict: "lottery_id,function_name,cache_key" });
}

